WITH payload AS (SELECT $archive_payload$[{"id":"99fb30b2-1466-5915-a5f4-3b6ca262dd39","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -مطالبة األخ عن اخواته برفع والية والده للعضل والغيبة والضرر -تعذر تبليغ املدعى عليه بالدعوى وباحلكم - قيام البينة على الدعوى بالشاهدين املعدلن -احلكم برفع والية األب الغائب وجعلها لأخ الشقيق -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","document_number":"34277095","case_number":"3459246","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"عضل -والية -مطالبة األخ عن اخواته برفع والية والده للعضل والغيبة والضرر -تعذر تبليغ املدعى عليه بالدعوى وباحلكم - قيام البينة على الدعوى بالشاهدين املعدلن -احلكم برفع والية األب الغائب وجعلها لأخ الشقيق -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه باحلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/3/15 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34277095 :‬‬\n                         ‫َر ْق ُم الدعوى‪3459246 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34389501‬تاريخه‪1434/12/26 :‬هـ‬\n\n\n     ‫عضــل ‪ -‬واليــة ‪ -‬مطالبــة األخ عــن اخواتــه برفــع واليــة والــده للعضــل‬\n     ‫والغيبــة والضــرر ‪ -‬تعــذر تبليــغ املدعــى عليــه بالدعــوى وباحلكــم ‪-‬‬\n     ‫قيــام البينــة علــى الدعــوى بالشــاهدين املعدلــن ‪ -‬احلكــم برفــع واليــة‬\n     ‫األب الغائــب وجعلهــا لــأخ الشــقيق ‪ -‬رفــع احلكــم حملكمــة االســتئناف‬\n                                          ‫لتعــذر تبليــغ املدعــى عليــه باحلكــم ‪.‬‬\n\n\n\n\n                         ‫‪ .1‬قوله تعالى (فال تعضلوهن أن ينكحن أزواجهن)‬\n     ‫‪ .2‬قــال ابــن قدامــة (فــإن رغبــت يف كــفء وأراد تزويجهــا لغيــره مــن‬\n                                 ‫أكفائهــا وامتنــع ‪...‬الــخ) املغنــى (‪)384/9‬‬\n             ‫‪ .3‬قال يف الشرح الكبير(وإن عضل األقرب زوج األبعد) ‪184/20‬‬\n     ‫‪ .4‬قــال يف األنصــاف (وإن عضــل األقــرب ز َّوج األبعــد هــذا الصحيــح مــن‬\n                                                           ‫املذهب‪...‬إلخ)‪184/20‬‬\n\n\n\n\n     ‫ا عــن أخواتــه دعــوى علــى والــده‬\n                                        ‫أقــام ابــن املدعــى عليــه بصفتــه وكي ـ ً‬\n     ‫وطالــب بنقــل واليــة النــكاح منــه إلــى مــن بعــده مــن األوليــاء‪ ،‬وذكــر‬\n     ‫أن موكالتــه بلغــن ســن الــزواج وتقــدم بهــن الســن فأكبرهــن يف‬\n     ‫األربعــن وأصغرهــن يف الثالثــن مــن عمرهــا وقــد تقــدم عــدة خطــاب‬\n‫‪85‬‬\n\f‫يصلحــون ملثلهــن وأن املدعــى عليــه رد اخلطــاب ألســباب غيــر مبــرره‪ ،‬لــم‬\n‫يحضــر املدعــى عليــه ولــم يــرد إلــى احملكمــة مــا يفيــد تبلغــه فأجــرت‬\n‫احملكمــة اتصــاال هاتفيــا علــى املدعــى عليــه فأفــاد بعلمــه بالدعــوى‬\n‫وأنــه ســوف يحضــر إذا فــرغ ‪ ،‬طلبــت احملكمــة مــن املدعــي البينــة علــى‬\n‫مــا ذكــره فأحضــر شــاهدين شــهدا بأنــه تقــدم ملــوكالت املدعــى عــدة‬\n‫خطــاب ولكــن والدهــن يــرد اخلطــاب وإن بعــض اخلطــاب تقدمــوا عــن‬\n‫طريــق الشــاهدين‪ُ ،‬عـ ِّـدلَ الشــاهدين‪ ،‬أحضــر املدعــي معــه الراغبــن‬\n‫بالنــكاح وأفــادا بأنهمــا تقدمــا لوالــد املدعيــات ورفــض تزويجهــم‪،‬‬\n‫وألنــه ظهــر للمحكمــة أن املدعــى عليــه ممتنــع عــن تزويــج املدعيــات‬\n‫أصالــة بنــاء علــى شــهادة الشــهود ومبــا أن الضــرر ظاهــر يف عــدم تزويــج‬\n‫املدعيــات الســيما وقــد تقــدم بهــن العمــر ومبــا أن منــع املــرأة مــن الــزواج‬\n‫بكــفء إذا طلبــت الــزواج بــدون مبــرر شــرعي هــو عضــل لهــا وملــا يترتــب‬\n‫علــى العضــل مــن أضــرار ولقولــه تعالــى (فــا تعضلوهــن أن ينكحــن‬\n‫أزواجهــن) لــذا فقــد ثبــت لــدى احملكمــة عضــل املدعــى عليــه لبناتــه‬\n‫وقــررت نقــل واليــة النــكاح إلــى مــن بعــده وهــم اإلخــوة األشــقاء واعتبــر‬\n     ‫هــذا احلكــم غيابيــا وبرفعــه حملكمــة االســتئناف جــرى تصديقــه‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة العامة وبناء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة وتاريــخ‬\n‫‪1434/02/05‬ه ـ املقيــدة باحملـكـم ــة برقــم وتـاري ــخ ‪1434/01/18‬ه ـ‬\n‫يف ي ــوم الثـالث ــاء الـمواف ــق‪1434/03/10‬هـ افـتتـح ــت اجللـس ــة السـاعـ ــة‬\n‫‪08 : 30‬وفيهــا وفيهــا حضــر ســعودي اجلنســية مبوجــب وكيــا عــن أوالد‬\n                                                                                        ‫‪86‬‬\n\f     ‫مبوجــب الوكالــة وتاريــخ ‪1433/9/12‬ه الصــادرة مــن كتابــة العــدل‬\n     ‫الثانيــة بالطائــف ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه ولــم يردنــا‬\n     ‫مــا يفيــد بتبليغــه وادعــى املدعــي وكالــة قائــا فيدعــواه إن املدعــى عليه‬\n     ‫ولــي التزويــج ملوكالتــي حيــث إنــه والدهــن وقــد بلغــن املدعيــات مبلــغ‬\n     ‫النســاء يف ســن الــزواج وتقــدم لهــن عــدة ُخ َّطــاب يصلحــون ملثلهــن إال أن‬\n     ‫املدعــى عليــه قــد رد اخلطــاب ألســباب غيــر مبــررة أطلــب نقــل الواليــة‬\n     ‫منــه إلــى مــن بعــده مــن األوليــاء هــذه دعــواي وألجــل حضــور املدعــى عليه‬\n     ‫قــررت رفــع اجللســة ثــم يف يــوم اإلثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه‬\n     ‫وال مــن ينــوب عنــه ولــم يردنامــا يفيــد تبلغــه وقــد جــرى االتصــال عليــه‬\n     ‫علــى جوالــه رقــم ‪ ...‬فأجــاب قائــا لــدي علــم بالدعــوى والتوفيــق بيــد‬\n     ‫اهلل وســوف أحضــر وقــت فراغــي وأنــا متواجــد يف الســعودية كمــا‬\n     ‫أضــاف املدعــي وكالــة أننــي مســتعد بإحضــار الكــفء الــذي تقــدم‬\n     ‫ملوكلتــي لــذا وألجــل حضــور املدعــى عليــه قــررت رفــع اجللســة ثــم يف‬\n     ‫يوماألربعــاء املوافــق‪ 1434/04/17‬ه ـ افتتحــت اجللســة الســاعةاحلادية‬\n     ‫عشــر والنصــف وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه‬\n     ‫وال مــن ينــوب ولــم يردنــا مــا يفيــد عــن ســبب تغيبــه ثــم أردف املدعــي‬\n     ‫وكالــة قائــا لقــد أحضــرت ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n     ‫رقــم و ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وهمــا رجــان‬\n     ‫عــدالن تقدمــا خلطبــة اخواتــي ولكــن أبــي يرفــض وبســؤالهما أجــاب‬\n     ‫احلاضــر األول ‪ ...‬لقــد تقدمــت ألحــد أخــوات احلاضــر () ولكــن والــده‬\n     ‫وعدنــي وقــال لــي خيــر ان شــاء اهلل ولــم يــرد علــي وقــد تزوجــت وهلل‬\n     ‫احلمــد ثــم أفــاد احلاضــر ‪ ...‬لقــد تقدمــت ألحــدى أخــوات احلاضــر ( )‬\n\n\n‫‪87‬‬\n\f‫قبــل ســنتني ولكــن املدعــى عليــه يرفــض حيــث ذهبــت لــه أربــع مــرات‬\n‫يرفــض وعنــد وصــول القضيــة عنــد هــذا احلــد‬        ‫أو أكثــر ولكنــه َ‬\n‫قــررت رفــع اجللســة ألجــل حضــور املدعــى عليــه ثــم يف يــوم األربعــاء‬\n‫املوافــق‪ 1434/05/22‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n‫صباحـ ًا وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن‬\n‫ينــوب عنــه وقــد وردتنــا إفــادة محضراخلصــوم باحملكمــة ‪ ...‬شــرح ًا علــى‬\n‫الطلــب يف ‪1434/4/17‬ه ـ واملتضمنــة أنــه لــم نســتدل إلــى منــزل املدعــى‬\n‫عليــه وفجــرى الوصــول إلــى عمــدة ‪ .....‬وأفــاد بأنــه غيــر معــروف لديهــم‬\n                       ‫أ‪.‬ه ـ وألجــل تبليــغ املدعــى عليــه قــررت رفــع اجللســة‪.‬‬\n‫ثــم يف يــوم اإلثنــن املوافــق‪ 1434/04/08‬ه ـ افتتحــت اجللســة الســاعة‬\n‫وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه وال مــن ينــوب‬\n‫عنــه ولــم يردنــا مــا يفيــد تبلغــه وقــد جــرى االتصــال عليــه علــى جوالــه‬\n‫رقــم فأجــاب قائــا لــدي علــم بالدعــوى والتوفيــق بيــد اهلل وســوف‬\n‫أحضــر وقــت فراغــي وأنــا متواجــد يف الســعودية كمــا أضــاف املدعــي‬\n‫وكالــة أننــي مســتعد بإحضــار الكــفء الــذي تقــدم ملوكلتــي لــذا‬\n                        ‫وألجــل حضــور املدعــى عليــه قــررت رفــع اجللســة‪.‬‬\n‫ثــم يف يــوم األربعــاء املوافــق‪ 1434/04/17‬ه ـ افتتحــت اجللســة الســاعة‬\n‫احلاديــة عشــر والنصــف وفيهــا حضــر املدعــي وكالــة ولــم يحضــر‬\n‫املدعــى عليــه وال مــن ينــوب ولــم يردنــا مــا يفيــد عــن ســبب تغيبــه ثــم‬\n‫أردف املدعــي وكالــة قائــا لقــد أحضــرت ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم و ســعودي اجلنســية مبوجــب وهمــا رجــان عــدالن‬\n‫تقدمــا خلطبــة اخواتــي ولكــن أبــي يرفــض وبســؤالهما أجــاب احلاضــر‬\n‫األول ‪ ...‬لقــد تقدمــت ألحــد أخــوات احلاضــر (‪ )...‬ولكــن والــده وعدنــي‬\n\n\n                                                                                      ‫‪88‬‬\n\f     ‫وقــال لــي خيــر إن شــاء اهلل ولــم يــرد علــي وقــد تزوجــت وهلل احلمــد ثــم‬\n     ‫أفــاد احلاضــر ‪ ...‬لقــد تقدمــت ألحــدى أخــوات احلاضــر (‪) ...‬قبــل ســنتني‬\n     ‫ولكــن املدعــى عليــه يرفــض حيــث ذهبــت لــه أربــع مــرات أو أكثــر‬\n     ‫يرفــض وعنــد وصــول القضيــة عنــد هــذا احلــد قــررت رفــع‬         ‫ولكنــه َ‬\n                                              ‫اجللســة ألجــل حضــور املدعــى عليــه‪.‬‬\n     ‫ثــم يف يــوم األربعــاء املوافــق‪ 1434/05/22‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫التاســعة والنصــف صباح ـ ًا وفيهــا حضــر املدعــي وكالــة ولــم يحضــر‬\n     ‫املدعــى عليــه وال مــن ينــوب عنــه وقــد وردتنــا إفــادة محضــر اخلصــوم‬\n     ‫باحملكمــة ‪ ...‬شــرح ًا علــى الطلــب رقــم ‪ 34953346‬يف ‪1434/4/17‬ه ـ‬\n     ‫واملتضمنــة أنــه لــم نســتدل إلــى منــزل املدعــى عليــه وفجــرى الوصــول إلى‬\n     ‫عمــدة ‪ ........‬وأفــاد بأنــه غيــر معــروف لديهــم أ‪.‬ه ـ وألجــل تبليــغ املدعــى‬\n                                                           ‫عليــه قــررت رفــع اجللســة‪.‬‬\n     ‫ثــم يف يــوم األربعــاء املوافق‪1434/07/19‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫احلاديــة عشــر وفيهــا حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليــه‬\n     ‫وال مــن ينــوب عنــه ولــم يردنــا مــا يفيــد عــن ســبب تغيبــه لــذا قررت الســير‬\n     ‫يف هــذه القضيــة وبســؤال املدعــي وكالــة عمــا اســتمهل ألجلــه أجــاب‬\n     ‫قائــا لقــدا حضــرت للشــهادة وأدائهــا شــاهدين فأذنــت للشــاهد األول‬\n     ‫بالدخــول فدخــل املدعــو ‪ ......‬والبالــغ مــن العمــر ‪ 54‬عامــا ويســكن يف‬\n     ‫حــي ‪ ......‬مبكــة ويعمــل وعالقتــه باملدعيــات أنهــن أبنــاء عمتــه وشــهد‬\n     ‫قائــا اشــهد بــاهلل تعالــى أن املدعــى عليــه قــد رفــض تزويــج بناتــه‬\n     ‫هكــذا شــهد ثــم أذنــت للشــاهد اآلخــر بالدخــول فدخــل ‪ ......‬والبالــغ من‬\n     ‫العمــر ‪ 33‬عامــا ويســكن يف ‪ ......‬ويعمــل يف ‪ ......‬وعالقتــه باملدعيــات‬\n     ‫أنــه جــار لهــم منــذ ثمانيــة ســنوات وشــهد قائــا اشــهد بــاهلل تعالــى بأنــه‬\n\n\n‫‪89‬‬\n\f‫تقــدم عــدة خطــاب ملــوكالت احلاضــر ولكــن والدهــن يــرد اخلطــاب‬\n‫ولقــد تقــدم أحدهــم مــن طــريف ولكــن والــد املدعــي رفــض اخلاطــب‬\n‫هكــذا شــهد ثــم حضــر ‪......‬ســعودي اجلنســية مبوجــب ‪......‬و‪......‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم‪ .....‬وعــدال الشــاهدين وذكــر‬\n‫بأنهمــا عدلــن مقبولــي الشــهادة لهمــا وعليهمــا وقــرر املدعــي وكالــة‬\n‫بــأن أقــرب عاصــب للمدعيــات هــو أخواتهــم األشــقاء (‪ ) ....‬وموكالتــي‬\n‫ليــس لديهــم مانــع مــن نقــل الواليــة لهــم ليتمكنــوا مــن تزويجهــن وقــد‬\n‫تضــررن موكلتــي مــن عضــل والــدي لهــن وأكبــر موكالتــي بلغــت ســن‬\n‫األربعــن والصغــرى منهــن بلغــت ســن الثالثــن هكــذا أضــاف فجــرى‬\n‫قفــل بــاب املرافعــة وبدراســة القضيــة والتأمــل وملــا ظهــر لنــا مــن حــال‬\n‫املدعــى عليــه مــن امتناعــه عــن تزويــج املدعيــات وبنــاء علــى شــهادة‬\n‫الشــهود املعدلــة شــرعا ومبــا أن الضــرر ظاهــر يف عــدم تزويــج املدعيــات‬\n‫ال ســيما وقــد تقــدم بهــن العمــر وملــا قــرر الفقهــاء بــأن األب إذا رد‬\n‫الكــفء يعــد عاضــا قــال ابــن قدامــة يف املغنــي (‪ )384/9‬فــإن رغبــت‬\n‫يف كــفء وأراد تزويجهــا لغيــره مــن أكفائهــا وامتنــع مــن تزويجهــا مــن‬\n‫الــذي إرادتــه كان عاضــا لهــن ومبــا أن منــع املــرأة مــن الــزواج بكــفء‬\n‫إذا طلبــت الــزواج بــدون مبــرر شــرعي هــو عاضــل لهــا وملــا يترتــب علــى‬\n‫العضــل مــن أضــرار منهــي عنهــا ولقولــه ســبحانه وتعالــى( فــا تعضلوهن‬\n‫أن ينكحــن أزواجهــن ) وإذا ثبــت عضــل والــد املدعيــات لهــن فــأن ذلــك‬\n‫ينقــل الواليــة إلــى األبعــد قــال يف الشــرح الكبيــر (‪ ( )184/20‬وإن‬\n‫عضــل األقــرب زوج األبعــد ) قــال يف اإلنصــاف يف طبعتــه مــع الشــرح‬\n‫الكبيــر واملقنــع (‪ ( )184/20‬وإن عضــل األقــرب زوج ‪ ......‬وقــررت مــا‬\n‫يلــي نقلــت واليــة النــكاح إلــى مــن بعــده وهــم األخــوة األشــقاء للمدعيــات‬\n\n\n                                                                                      ‫‪90‬‬\n\f     ‫وهــم وبذلــك حكمــت وبعــرض ذلــك علــى املدعــي وكالــة احلاضــر قــررا‬\n     ‫القناعــة ويعــد هــذا احلكــم حكمــا غيابيــا يف املدعــى عليــه وســوف‬\n     ‫يجــري بعــث نســخه مــن احلكــم إلبــداء قناعتــه مــن عدمــه وبــاهلل‬\n     ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                            ‫حــرر يف ‪1434/7/19‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد وبعــد رفــع احلكــم حملكمــة االســتئناف أعيــد‬\n     ‫بالقــرار الصــادر مــن الدائــرة األولــى لألحــوال الشــخصية برقــم‬\n     ‫‪ 34389501‬وتاريــخ ‪ 1434/12/26‬ه ـ املتضمــن وبدراســة الصــك‬\n     ‫وصــورة ضبطــة تقــرر املوافقــة علــى احلكــم أ‪.‬ه ـ وحتــى ال يخفــى جــرى‬\n     ‫إحلاقــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلى آله وصحبه‬\n                                                  ‫وســلم ‪ .‬حــرر يف ‪1435/1/11‬هــ‪.‬‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد نحــن قضــاة الدائــرة‬\n     ‫األولــى لألحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n     ‫يف محكمــة االســتئناف جــرى منــا االطــاع علــى املعاملــة الــواردة إلينــا‬\n     ‫شــفع خطــاب فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1434/11/26‬ه‬\n     ‫املشــتملة علــى الصــك وتاريــخ ‪1434/7/23‬ه ـ الصــادر مــن فضيلــة‬\n     ‫الشــيخ القاضــي باحملكمــة العامــة مبكــة املكرمــة املتضمــن دعــوى‬\n     ‫يف عضــل وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪91‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":85,"source_page_end":91,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e220359d4bef4116b490749dfcef6127cabc7bd3e2aa14f217f7d5754a91f643","normalized_text_hash":"0cd02a8d37d2d50827dd972375391ddff7d7d714d3659993085160747c0f374f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p85-34277095"},{"id":"bd48bd6f-5a88-55ff-8923-58d9880b95d8","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -طلب نقل والية -أخ منع أخواته من الزواج -عدم حضور املدعى عليه إلى المحكمة -قطع اللدد واملماطلة ورفع الضرر من فقه املرافعات -البينة بشهادة الشهود العدول -عضل املدعى عليه ألخواته من النكاح -انتقال والية النكاح إلى احلاكم الشرعي إذا ثبت عضل الولي -احلكم بثبوت عضل الولي للمدعتني ونقل الوالية للحاكم الشرعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","document_number":"33366895","case_number":"32541131","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بتبوك","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/5","year":"1434","subject":"عضل -والية -طلب نقل والية -أخ منع أخواته من الزواج -عدم حضور املدعى عليه إلى المحكمة -قطع اللدد واملماطلة ورفع الضرر من فقه املرافعات -البينة بشهادة الشهود العدول -عضل املدعى عليه ألخواته من النكاح -انتقال والية النكاح إلى احلاكم الشرعي إذا ثبت عضل الولي -احلكم بثبوت عضل الولي للمدعتني ونقل الوالية للحاكم الشرعي -رفع احلكم حملكمة الاستئناف لتعذر تبليغ املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/8/5 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪33366895 :‬‬\n                   ‫َر ْق ُم الدعوى‪32541131 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 3456883‬تاريخه‪1434/3/7:‬هـ‬\n\n\n\n‫عضــل ‪ -‬واليــة ‪ -‬طلــب نقــل واليــة ‪ -‬أخ منــع أخواتــه مــن الــزواج ‪ -‬عــدم‬\n‫حضــور املدعــى عليــه إلــى احملكمــة ‪ -‬قطــع اللــدد واملماطلــة ورفــع‬\n‫الضــرر مــن فقــه املرافعــات ‪ -‬البينــة بشــهادة الشــهود العــدول ‪ -‬عضــل‬\n‫املدعــى عليــه ألخواتــه مــن النــكاح ‪ -‬انتقــال واليــة النــكاح إلــى احلاكــم‬\n‫الشــرعي إذا ثبــت عضــل الولــي ‪ -‬احلكــم بثبــوت عضــل الولي للمدعتني‬\n‫ونقــل الواليــة للحاكــم الشــرعي‪ -‬رفــع احلكــم حملكمــة االســتئناف‬\n                                                 ‫لتعــذر تبليــغ املدعــى عليــه ‪.‬‬\n\n\n\n\n‫‪1 .1‬قولــه صلــى اهلل عليــه وســلم ‪ ( :‬إذا أتاكــم مــن ترضــون دينــه وخلقه‬\n            ‫فزوجــوه إال تفعلــوا تكــن فتنــة يف األرض وفســاد كبير ) ‪.‬‬\n                     ‫‪2 .2‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n‫‪3 .3‬مذهــب جمهــور الفقهــاء األربعــة أن الواليــة تنتقــل مــن العاضــل‬\n                                               ‫إلــى احلاكــم الشــرعي ‪.‬‬\n‫‪4 .4‬قــال ابــن قدامــه يف املغنــي ( ‪ « : ) 383 - 382/9‬احلكــم الثالــث‬\n‫إذا عضلهــا وليهــا األقــرب انتقلــت الواليــة إلــى األبعــد نــص عليــه‬\n‫أحمــد وعنــه روايــة أخــرى تنتقــل إلــى الســلطان ‪ ،‬وهــو اختيــار أبــي‬\n‫بكــر وذكــر ذلــك عــن عثمــان بــن عفــان رضــي اهلل عنــه وشــريح‪ ،‬وبه‬\n‫قــال الشــافعي‪ ،‬لقــول النبــي صلــى اهلل عليــه وســلم ( فــإن اشــتجروا‬\n\n                                                                                     ‫‪92‬‬\n\f                                          ‫فالســلطان ولــي مــن ال ولــي لــه ) ‪.‬‬\n                                          ‫‪5 .5‬القاعدة الفقهية ( الضرر يزال ) ‪.‬‬\n\n\n\n\n     ‫ادعــت املدعيتــان أن املدعــى عليــه عضلهمــا وهــو أخوهمــا الشــقيق‬\n     ‫األكبــر ووالدهــم متوفــى كمــا ثبــت يف صــك حصــر الورثــة وقــد بلغــن‬\n     ‫مبلــغ النســاء وقــد تقــدم لهــن خطــاب وأخوهــم املدعــى عليــه يرفــض دون‬\n     ‫ســبب وبقيــة إخوتهمــا أصحــاب ســوابق وقامــوا بطردهمــا مــن البيــت‬\n     ‫وضربهمــا ويســكنان دار الرعايــة وإحــدى املدعيتــن لــم يســبق لهــا‬\n     ‫الــزواج واألخــرى تــويف عنهــا زوجهــا وتطلبــان نقــل الواليــة مــن أخيهــن‬\n     ‫املدعــى عليــه إلــى احلاكــم الشــرعي ‪ ،‬لــم يحضر املدعــى عليه ولم يقدم‬\n     ‫عــذر ًا وقــد مت تبليغــه عــن طريــق وحــدة التحريــات والبحــث اجلنائــي ‪،‬‬\n     ‫علمـ ًا بــأن املدعــى عليــه مــن خــال جمــع املعلومــات لــدى اجلهــة املختصــة‬\n     ‫متهــرب عــن األنظــار ومت فصلــه مــن عملــه ومت طرده هــو وزوجته من بيت‬\n     ‫والدهــم وبقيــة أشــقائه مــن أربــاب الســوابق واملشــبوهني ولديهــم قضايــا‬\n     ‫إطــاق نــار وتوجــد لديهــم مراقبــة دائمــة علــى بيتهــم للقبــض عليهــم‪،‬‬\n     ‫قــرر ناظــر القضيــة ســماع الدعــوى غيابيـ ًا نظــر ًا لتضــرر املدعيتــن مــن‬\n     ‫عــدم حضــور املدعــى عليــه رغــم طلبــه عــدة مــرات بشــتى الطــرق ألن‬\n     ‫قطــع اللــدد واملماطلــة ودفــع الضــرر مــن فقــه املرافعــات‪،‬مت طلــب البينــة‬\n     ‫مــن املدعيتــن علــى صحــة دعواهمــا فشــهدت البينــة الشــرعية علــى‬\n     ‫أن املدعــى عليــه قــد عضــل املدعيتــن مــن الــزواج وبقيــة إخوانهمــا مــن‬\n     ‫أصحــاب املشــاكل ومــن أربــاب الســوابق وقــد جــرى تعديــل الشــاهدين‬\n     ‫حســب األصــول الشــرعية‪ ،‬عــدم حضــور املدعــى عليــه يعتبــر نكــو ًال‬\n\n‫‪93‬‬\n\f‫عــن اخلصومــة‪ ،‬ألن مــن دعــي إلــى القضــاء وجــب عليــه أن يجيــب‪،‬‬\n‫دل الدليــل الشــرعي أن رد املدعــى عليــه للخطــاب األكفــاء فيــه فتنــة‬\n‫وفســاد كبيــر‪ ،‬والضــرر يــزال يف الشــريعة‪ ،‬ذهــب جمهــور الفقهــاء‬\n‫األربعــة إلــى أن الواليــة تنتقــل مــن العاضــل إلــى احلاكــم الشــرعي‪ ،‬فمــن‬\n‫امتنــع عــن حــق قــام احلاكــم مقامــه‪ ،‬مثــل مــا لــو كان عليــه ديــن فامتنــع‬\n‫مــن قضائــه‪ ،‬احلكــم بثبــوت عضــل املدعــى عليــه للمدعيتــن‪ ،‬احلكــم‬\n‫بنقــل الواليــة مــن املدعــى عليــه إلــى احلاكــم الشــرعي‪ ،‬مت بعــث نســخة‬\n‫مــن احلكــم إلــى املدعــى عليــه ليقــدم اعتراضــه يف املــدة النظاميــة فــإن‬\n‫تعــذر فســوف يتــم رفــع املعاملــة حملكمــة االســتئناف‪ ،‬صــدق احلكــم‬\n                                                   ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n‫بتبــوك وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بتبــوك املســاعد برقــم ‪ 32541131‬وتاريــخ ‪1432/11/19‬ه ـ‬\n‫املـقـيـدة باحملكـمـة برقم ‪ 321478079‬وتاريخ ‪1432/11/19‬هـ فـفـي‬\n‫يــوم الـثـالث ــاء الـمــواف ــق ‪1433/06/17‬ه ـ افـتـتـح ــت اجل ـلـس ــة الـسـاع ــة‬\n‫‪ 12 : 40‬وفيهــا حضــرت ‪ ........‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪........‬كمــا حضــرت ‪........‬ســعودية اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ........‬ولــم يحضــر املدعــى عليــه ‪........‬وال مــن ينــوب عنــه ولــم يقــدم‬\n‫عــذر ًا عــن عــدم احلضــور وباالطــاع علــى املعاملــة وجــد فيهــا مــا يلــي أو ًال‬\n‫إفــادة وحــدة اإلحضــار بشــأن تبليــغ املدعــى عليــه مبوعــد اجللســة احملــدد‬\n‫بتاريــخ ‪1432/12/18‬ه ـ املتضمــن بأنــه مت اخلروج إلــى مقر عمل املدعى‬\n                                                                                          ‫‪94‬‬\n\f     ‫عليــه ولــم يكــن متواجــد ًا ومت تســليم مديــر املدرســة ورقــة التبليــغ وأخــذ‬\n     ‫توقيعــه عليــه وتعهــد بتبليــغ املدعــى عليــه ‪ .‬ثاني ـ ًا ‪ :‬وردنــا خطــاب مديــر‬\n     ‫إدارة التحريــات والبحــث اجلنائــي ذي الرقــم ‪........‬يف ‪1433/5/26‬ه ـ‬\n     ‫اجلــواب علــى خطابنــا ذي الرقــم ‪ 3356451‬يف ‪1433/1/9‬ه ـ وهذا نصه‬\n     ‫« نفيــد فضيلتكــم بــأن املذكــور كان يعمــل مســتخدم ب‪........‬بحــي‬\n     ‫‪........‬وقــد مت االنتقــال إلــى موقــع عملــه واتضــح أنــه غيــر موجــود وبعــد‬\n     ‫علمــه بحضورنــا تغيــب عــن احلضــور إلــى عملــه حتــى مت طــي قيــده نهائيـ ًا‬\n     ‫‪ .‬مت االنتقــال إلــى منزلــه الكائــن بحــي ‪........‬بالقــرب مــن صالــة ‪........‬‬\n     ‫لألفــراح عــدة مــرات يف أوقــات متفاوتــه وطــرق البــاب إال أنــه لــم يجيــب‬\n     ‫أحــد نهائي ـ ًا ‪ .‬مت متابعــة منزلــه مــن قبلنــا بطريقــة ســرية ولــم نالحــظ‬\n     ‫خروجــه مــن املنــزل واتضــح أن ســيارته متوقفــة مــن فتــرة طويلــة أمــام‬\n     ‫املنــزل ولــم تتحــرك ‪ .‬اتضــح لدينــا أن املذكــور قــام بتــرك أبنائــه باملنــزل‬\n     ‫وجعلهــم يتغيبــون عــن احلضــور للمدرســة ‪ .‬مت التوجــه إلــى املذكــور‬\n     ‫رفــق عمــدة احلــي عــدة مــرات إلــى منــزل املذكــور ولــم جنــد أحــد ويف‬\n     ‫يــوم الثالثــاء املوافــق ‪1433/5/25‬ه ـ قــام املذكــور بفتــح بــاب املنــزل‬\n     ‫وأفــاد مــن داخــل منزلــه بأنــه ســوف يحضــر لنــا يــوم الســبت املوافــق‬\n     ‫‪1433/5/29‬ه ـ ‪ .‬بجمــع املعلومــات عــن املذكــور اتضــح أنــه ســبق أن‬\n     ‫مت طــرده هــو وزوجتــه وأبنائــه مــن منــزل والدهــم والــذي كان يســكن‬\n     ‫فيــه مــن قبــل أشــقائه ‪ .‬بقيــة أشــقائه مــن أربــاب الســوابق واملشــبوهني‬\n     ‫ولديهــم قضايــا إطــاق نــار وحاليـ ًا توجــد مراقبــة دائمــة علــى منزلهــم من‬\n     ‫اجــل القبــض عليهــم ‪ .‬كمــا أن املعلومــات تفيــد يقومــون بإســاءة معاملــة‬\n     ‫والدتهــم وقامــوا بطردهــا وهــي تقيــم حالي ـ ًا لــدى شــقيقها وســوف يتــم‬\n     ‫ـاء علــى مــا ســبق ونظــر ًا‬\n                                 ‫بعــث املذكــور لكــم عنــد إحضــاره ‪ .‬أ ه ـ فبنـ ً‬\n\n‫‪95‬‬\n\f‫لتضــرر املدعيتــن مــن عــدم حضــور املدعــى عليــه رغــم طلبــه عــدة مــرات‬\n‫بشــتى الطــرق وحيــث إن قطــع اللــدد واملماطلــة ودفــع الضــرر مــن فقــه‬\n‫املرافعــات املعتــد بــه لــذا فقــد قــررت نظــر الدعــوى غيابي ـ ًا وبســؤال‬\n‫املدعيتــن عــن دعواهمــا قالتــا إن املدعــى عليــه هــو أخونــا الشــقيق‬\n‫األكبــر حيــث إن والــدي متــويف حســب صــك حصــر الورثــة الصــادر‬\n‫مــن هــذه احملكمــة برقــم ‪........‬بتاريــخ ‪1421/2/24‬ه ـ وقــد بلغنــا‬\n‫مبلــغ النســاء وقــد تقــدم لنــا خطــاب إال أن أخــي يرفضهــم بــدون ســبب‬\n‫علم ـ ًا بــأن بقيــة أخواننــا أصحــاب ســوابق وقــد ســبق أن طردونــا مــن‬\n‫البيــت وقامــوا بضربنــا وهــم معروفــون باجلرميــة لــدى اجلهــات املختصــه‬\n‫ونحــن اآلن نســكن يف دار الرعايــة علم ـ ًا بأننــي أنــا املدعيــة ‪........‬لــم‬\n‫يســبق لــي الــزواج وأنــا املدعيــة الثانيــة تزوجــت مــن املدعــو ‪........‬وتــويف‬\n‫بتاريــخ ‪1430/5/17‬ه ـ حســب صــك حصــر الورثــة الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪........‬بتاريــخ ‪1430/8/13‬ه ـ املجلــد رقــم ‪ ، 1‬نطلــب‬\n‫نقــل الواليــة مــن أخينــا املدعــى عليــه إلــى احلاكــم الشــرعي هــذه دعوانــا‬\n‫هكــذا ادعتــا وبســؤالهما عــن البينــة التــي تؤيــد صحــة دعواهمــا قالتــا‬\n‫ـاء عليــه رفعــت اجللســة ثــم‬ ‫ســنحضرها اجللســة القادمــة إن شــاء اهلل وبنـ ً‬\n‫يف يــوم اإلثنــن املوافــق‪ 1433/06/23‬ه ـ افتتحــت اجللســة الســاعة ‪: 17‬‬\n‫‪ 01‬وفيهــا حضــرت املدعيتــان ولــم يحضــر املدعــى عليــه وقــد جــرى منــي‬\n‫ســؤال املدعيتــن عــن البينــة التــي وعدتــا باحضارهــا فأحضرتا للشــهادة‬\n‫ال مــن ‪........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬    ‫وأدائهــا ك ً‬\n‫‪........‬و‪........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقم ‪ ........‬وبســؤال‬\n‫الشــاهد األول ‪........‬عمــا لديــه مــن شــهادة قــال بأننــي ليــس بينــي وبــن‬\n‫املدعيتــن صلــة قرابــة وأنــا مــن مواليــد عــام ‪1397‬ه ـ وأشــهد هلل تعالــى‬\n\n\n                                                                                        ‫‪96‬‬\n\f     ‫بأننــي أعــرف املرأتــن ‪........‬و‪ ........‬أبنتــي ‪........‬حيــث إنهمــا مــن جيراننــا‬\n     ‫وأشــهد بــأن أخاهمــا ‪........‬قــد عضلهمــا عــن الــزواج رغــم تقــدم اخلطــاب‬\n     ‫األكفــاء لهمــا وأن بقيــة أخوانهمــا أصحــاب مشــاكل ومــن أربــاب‬\n     ‫الســوابق وســبق أن أودعــت املــرأة ‪........‬دار احلمايــة بســبب مشــاكل‬\n     ‫أخوانهــا هــذا مــا لــدي من شــهادة كما شــهد الشــاهد الثانــي ‪........‬بقوله‬\n     ‫بأننــي جــار املدعيتــن وليــس بينــي وبينهمــا صلــة قرابــة وأنــا مــن مواليــد‬\n     ‫عــام ‪1408‬ه ـ وأشــهد هلل تعالــى بــأن أخ املدعيتــن ‪........‬يرفــض تزويجهن‬\n     ‫ومياطــل فيهــن رغــم تقــدم اخلطــاب األكفــاء لهــن وأمــا بقيــة أخوانهمــا‬\n     ‫فهــم أصحــاب مشــاكل ومــن أربــاب الســوابق هــذا مــا لــدي مــن شــهادة‬\n     ‫وبســؤال املدعيتــن عــن املزكيــن للشــاهدين قالتــا أننــا ســنحضرهما‬\n     ‫ـاء عليــه رفعــت اجللســة ثــم‬  ‫يف اجللســة القادمــة إن شــاء اهلل تعالــى وبنـ ً‬\n     ‫يف يــوم اإلثنــن املوافــق‪ 1433/06/30‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 12 :00‬وفيهــا حضــرت املدعيتــان ولــم يحضــر املدعــى عليــه وبســؤال‬\n     ‫املدعيتــن عــن املزكيــن الذيــن وعدتــا بإحضارهمــا أحضرتــا للشــهادة‬\n     ‫ال مــن ‪........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬       ‫وأدائهــا ك ً‬\n     ‫‪........‬و‪........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪........‬فشــهدا‬\n     ‫ـاء‬\n     ‫جميع ـ ًا بعدالــة الشــاهدين ‪........‬و‪........‬وأنهمــا مرضيــا الشــهادة فبنـ ً‬\n     ‫علــى مــا تقــدم مــن الدعــوى وحيــث إن املدعيتــن طلبتــا نقــل الواليــة‬\n     ‫مــن املدعــى عليــه إلــى احلاكــم الشــرعي لألســباب املوضحــة بدعواهــا‬\n     ‫وحيــث إن املدعــى عليــه قــد أمتنــع عــن احلضــور رغــم طلبــه عــدة مــرات‬\n     ‫وبطــرق شــتى وحيــث إن عــدم حضــور املدعــى عليــه يعتبــر نكــو ًال عــن‬\n     ‫اخلصومــة ألن مــن دعــي إلــى القضــاء وجــب عليه أن يجيــب وحيث أقامت‬\n     ‫املدعيتــان البينــة املعدلــة شــرع ًا علــى عضــل املدعــى عليــه لهمــا وأن بقيــة‬\n\n\n‫‪97‬‬\n\f‫إخوتهمــا مــن أربــاب الســوابق وحيــث إن يف رد املدعــى عليــه للخطــاب‬\n‫األكفــاء فيــه فتنــة وفســاد كبيــر لقولــه صلــى اهلل عليــه وســلم « إذا‬\n‫أتاكــم مــن ترضــون دينــه وخلقــه فزوجــوه وإال تفعلــوه تكــن فتنــة يف‬\n‫األرض وفســاد كبيــر وحيــث إن يف الــزواج مــن إعفــاف الزوجــن ودفــع‬\n‫الضــرر مــا ال يخفــى ال ســيما يف هــذا الزمــن الــذي كثــرت فيــه الفــن‬\n‫وألن الضــرر يــزال لقولــه صلــى اهلل عليــه وســلم « ال ضــرر وال ضــرار‬\n‫«وحيــث إن نقــل الواليــة مــن الولــي املدعــى عليــه إلــى غيــره مــن أقــارب‬\n‫املدعيتــن رمبــا أفضــى إلــى النــزاع واخلصــام وقطيعــة الرحــم ال ســيما‬\n‫وأن إخــوان املدعيتــن مــن أصحــاب املشــاكل وأربــاب الســوابق كمــا‬\n‫شــهدت بذلــك البينــة وكمــا جــاء يف احملضــر املعــد مــن البحــث اجلنائــي‬\n‫وألن الشــريعة تتطلــع إلــى قطــع النــزاع وعــدم التقاطــع والتدابــر وحيــث‬\n‫إن مذهــب جمهــور الفقهــاء األربعــة أن الواليــة تنتقــل مــن العاضــل إلــى‬\n‫احلاكــم الشــرعي قــال أبــن قدامــه يف املغنــي (‪ )383-382/9‬مــا نصــه‬\n‫« احلكــم الثالــث إذا عضلهــا وليهــا األقــرب أنتقلــت الواليــة إلــى األبعــد‬\n‫نــص عليــه أحمــد وعنــه روايــة أخــرى تنتقــل إلــى الســلطان وهــو أختيــار‬\n‫أبــي بكــر وذكــر ذلــك عــن عثمــان بــن عفــان رضــي اهلل عنــه وشــريح‬\n‫وبــه قــال الشــافعي لقولــه النبــي صلــى اهلل عليــه وســلم فــإن اشــتجروا‬\n‫فالســلطان ولــي مــن ال ولــي لــه « وألن ذلــك حــق امتنــع مــن أدائــه فقــام‬\n‫احلاكــم مقامــه كمــا لــو كان عليــه ديــن فأمتنــع مــن قضائــه وعليــه وملا‬\n‫تقــدم كلــه فقــد ثبــت لــدي عضــل املدعــى عليــه للمدعيتــن وقــررت نقــل‬\n‫الواليــة منــه إلــى احلاكــم الشــرعي وبــه حكمــت وقــررت بعــث نســخة‬\n‫مــن احلكــم للمدعــى عليــه ليقــدم اعتراضــه عليــه إن رغــب خــال مــدة‬\n‫االعتــراض وقدرهــا ثالثــون يوم ـ ًا مــن تاريــخ اســتالم احلكــم وإن تعــذر‬\n\n\n                                                                                    ‫‪98‬‬\n\f     ‫تســليمه فســوف يتــم رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n     ‫حســب املتبــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1433/06/30‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/04/03‬ه ـ‬\n     ‫افتتحــت اجللســة الســاعة ‪ 10 : 00‬وقــد عــادت املعاملــة مــن محكمــة‬\n     ‫االســتئناف مبنطقــة تبــوك برقــم ‪ 34353958‬وتاريــخ ‪1434/3/21‬ه ـ‬\n     ‫وبرفقهــا قــرار تصديــق األحــوال الشــخصية رقــم ‪ 3456883‬وتاريــخ‬\n     ‫‪1434/3/7‬ه ـ ( املتضمــن املوافقــة علــى احلكــم ) أ ‪ .‬هـ وباهلل التوفيق‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                   ‫‪1434/04/03‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد‪ :‬فقــد اطلعن ــا نحــن قـض ــاة دائــرة األحــوال‬\n     ‫الشــخصية يف محكمــة االســتئناف مبنطقــة تبــوك علــى املعاملــة الواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة العامة بتبوك املكلــف برقم ‪321478079‬‬\n     ‫وتاريــخ ‪1434/2/3‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n     ‫‪ ........‬وفقــه اهلل برقــم‪ 33366895 /‬وتاريــخ ‪1434/8/5‬ه ـ اخلــاص‬\n     ‫بدعــوى عضــل مقدمــه مــن ‪........‬ضــد ‪........‬وقــد تضمــن الصــك حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدارســة الصــك وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة جــرت املصادقــة علــى احلكــم باألكثريــة ‪.‬واهلل املوفــق‬\n                            ‫وصلــى اهلل علــى نبينــا م حمــد وآلــه وص حبــه وســلم‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":92,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5d905f01a137e69cbbcee1769a2b3e755bf0225bdc41fb771a8e47317a116da2","normalized_text_hash":"2e6959bb1024fd721ed7ea513c5863c7fb17166ddc3a5a2d571fc0339ebc9f52","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p92-33366895"},{"id":"51420aec-2ed5-50d4-badc-f428ee2de385","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -مطالبة بنتن بإثبات عضل والدهما ورفع واليته عنهما وجعلها ألخيهما أنكر املدعى عليه العضل وقرر موافقته على التزويج ثم ماطل واشترط شروطا -طالبت أم املدعيتن برفع والية األب عن بقية بناتها -شهادة الشاهدين بعضل املدعى عليه وإفادات اخلطاب -احلكم بثبوت عضل األب ورفع واليته وجعلها","document_number":"3462992","case_number":"33564272","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"عضل -والية -مطالبة بنتن بإثبات عضل والدهما ورفع واليته عنهما وجعلها ألخيهما أنكر املدعى عليه العضل وقرر موافقته على التزويج ثم ماطل واشترط شروطا -طالبت أم املدعيتن برفع والية األب عن بقية بناتها -شهادة الشاهدين بعضل املدعى عليه وإفادات اخلطاب -احلكم بثبوت عضل األب ورفع واليته وجعلها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/3/15 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3462992 :‬‬\n                   ‫َر ْق ُم الدعوى‪33564272 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34207876‬تاريخه‪1434/11/24:‬هـ‬\n\n\n\n‫عضــل ‪ -‬واليــة ‪ -‬مطالبــة بنتــن بإثبــات عضــل والدهمــا ورفــع واليتــه‬\n‫عنهمــا وجعلهــا ألخيهمــا أنكــر املدعــى عليــه العضــل وقــرر موافقتــه‬\n‫علــى التزويــج ثــم ماطــل واشــترط شــروطا ‪ -‬طالبــت أم املدعيتــن برفــع‬\n‫واليــة األب عــن بقيــة بناتهــا‪ -‬شــهادة الشــاهدين بعضــل املدعــى عليــه‬\n‫وإفــادات اخلطــاب ‪ -‬احلكــم بثبــوت عضــل األب ورفــع واليتــه وجعلهــا‬\n                                                                    ‫لــأخ ‪.‬‬\n\n\n\n\n‫‪-1‬قــال اهلل تعالــى (وأنكحــوا األيامــى منكــم والصاحلــن مــن عبادكــم‬\n                                                                    ‫وإمائكــم)‪.‬‬\n‫‪-2‬قــول الرســول صلــى اهلل عليــه وســلم ( إذا أتاكــم مــن ترضــون دينــه‬\n‫وخلقــه فأنكحــوه إال تفعلــوا تكــن فتنــة يف األرض وفســاد كبيــر)‬\n                                                           ‫أخرجــه الترمــذي‪.‬‬\n   ‫‪-3‬قول الرسول صلى اهلل عليه وسلم (السلطان ولي من ال ولي له)‪.‬‬\n‫‪ -4‬قــال ابــن قدامــة (ومعنــى العضــل منــع املــرأة مــن التزويــج بكفئهــا‬\n                                          ‫إذا طلبــت ذلــك ‪....‬إلــخ) املغنــي‪.‬‬\n‫‪-5‬قــال املباركفــوري (فســاد عريــض أي ذو عــرض أي كبيــر وذلــك‬\n‫ألنكــم إن لــم تزوجوهــا إال مــن ذي مــال أو جــاه ‪ ....‬إلــخ) حتفة األحوذي‬\n‫‪-6‬قــال ابــن رشــد رحمــه اهلل (واتفقــوا علــى أنــه ليــس للولــي أن يعضــل‬\n\n                                                                                  ‫‪100‬‬\n\f                                                                    ‫موليتــه إلــخ ‪)...‬‬\n      ‫‪-7‬قــال ابــن تيميــة رحمــه اهلل يف مجمــوع الفتــاوى( فليــس للولــي أن‬\n                                    ‫يجبرهــا علــى نــكاح مــن ال ترضــاه ‪......‬الــخ)‬\n      ‫‪-8‬قــال البهوتــي (لــو عضــل األقــرب ز ّوج األبعــد يعنــي مــن يلــي األقــرب‬\n                                          ‫مــن األوليــاء ‪ ......‬الــخ) كشــاف القنــاع‬\n\n\n\n\n      ‫ادعــت بنتــان دعــوى علــى والدهمــا يطالبــان بفســخ واليتــه لعضلــه‬\n      ‫وإعطائهــا ألخيهمــا الشــقيق‪ ،‬أنكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n      ‫العضــل واســتعد بتزويــج الفتيــات متــى تقــدم الرجــل املناســب ‪ ،‬ذكــرت‬\n      ‫إحــدى املدعيتــن أنــه تقــدم لهــا يف الوقــت احلاضــر خاطــب وطلبــت‬\n      ‫تزويجهــا بــه وطلــب املدعــى عليــه مهلــة للســؤال عنــه‪،‬ويف جلســة أخــرى‬\n      ‫ذكــر املدعــى عليــه أنــه اليــزال يســأل عــن اخلاطــب وأحوالــه ثــم تخلــف‬\n      ‫املدعــى عليــه عــن جلســة أخــرى وحضــرت فيهــا أم البنتــن وذكــرت أنــه‬\n      ‫تقــدم خطــاب لبناتهــا للمدعــى عليــه وأنه رفض تزويجهمــا وطالبت برفع‬\n      ‫واليــة املدعــى عليــه عــن بقيــة بناتهــا حتــى ال يتضــررن ‪،‬كمــا حضر لدى‬\n      ‫احملكمــة أحــد اخلطــاب وذكــر أنــه ذهــب للمدعــى عليــه وطلــب منــه‬\n      ‫تزويجــه بإحــدى املدعيــات إال أنــه ماطــل ولــم يــرد عليــه وأحضــر اخلاطــب‬\n      ‫مشــهدا مــن إمــام املســجد يثبــت التزامــه بــأداء الصــاة كمــا أحضــر‬\n      ‫شــاهدين شــهدا بأنــه كــفء وصالــح للــزواج كمــا شــهد الشــاهدان‬\n      ‫بأنــه تقــدم للمدعيــات عــدة خطــاب وأن املدعــى عليــه رفــض تزويجهمــا‪،‬‬\n      ‫وقــد جــرى تزكيــة الشــاهدين‪ ،‬ثــم ســألت احملكمــة املدعــى عليــه عــن‬\n      ‫اخلاطــب الــذي تقــدم ألحــد بناتــه أثنــاء نظــر القضيــة وطلــب الســؤال عنــه‬\n‫‪101‬‬\n\f‫فقــرر انــه ال مانــع لديــه مــن تزويجــه بشــروط منهــا أن يكــون املؤخــر‬\n‫خمســن ألــف ريــال وعارضــت املدعيــة علــى هــذا الشــرط ألنــه ينفــر‬\n‫اخلاطــب وذكــرت أن أختهــا الكبــرى تزوجــت بثالثــن ألــف ريــال‬\n‫وبــدون مؤخــر وبعــرض ذلــك علــى املدعــى قــال هــذا أمــر يخصنــي ثــم‬\n‫قــام بســب أوالده ودعــا عليهــم ‪ -‬بنــاء علــى شــهادة الشــاهدين املعدلــن‬\n‫املتضمنــة عضــل املدعــى عليــه البنتيــه املدعيتــن ومبــا أن النــكاح حــق‬\n‫للمــرأة ال يجــوز لوليهــا منعــه منــه (ولقولــه صلــى اهلل عليــه وســلم إذا‬\n‫أتاكــم مــن ترضــون دينــه وخلقــه فأنكحــوه إال تفعلــوا تكــن فتنــة‬\n‫يف األرض وفســاد كبيــر) وألن الضــرر يــزال يف الشــريعة والعاضــل‬\n‫تــزول واليتــه بامتناعــه‪ ،‬وألن والــدة املدعيتــن وبقيــة بنــات املدعــى عليــه‬\n‫تقدمــن بطلــب شــمول بقيــة البنــات برفــع واليــة األب وألنــه ثبــت لــدى‬\n‫احملكمــة عضــل املدعــى عليــه البنتيــه املدعيتــن فيقــاس عليهــن بقيــة‬\n‫بناتــه وألن إقامــة الدعــوى مــرة أخــرى لرفــع واليــة األب عــن بقيــة البنــات‬\n‫قــد تنفــر اخلاطــب مســتقبال؛ لــذا ثبــت لــدى احملكمــة عضــل املدعــى‬\n‫عليــه البنتيــه املدعيتــن وجعلــت واليــة التزويــج جلميــع البنــات ألخيهــن‬\n                        ‫الشــقيق ‪،‬اعتــرض املدعــى عليــه‪ ،‬صــدق احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬املــازم القضائــي لــدى فضيلــة‬\n‫الشــيخ ‪ ......‬القاضــي يف احملكمــة العامــة وبنــاء علــى املعاملــة احملالــة‬\n‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1433/09/06‬ه ـ‬\n‫املقيــدة باحملكمــة وتاريــخ ‪1433/09/06‬ه ـ يف يــوم الســبت‬\n‫املوافق‪1434/02/02‬هـ حضرت ‪ ......‬ســعودية اجلنســية مبوجب الســجل‬\n                                                                                      ‫‪102‬‬\n\f      ‫املدنــي رقــم ‪ ......‬و‪ ......‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪ ......‬واملعــرف بهمــا مــن قبــل أخيهمــا ‪ ......‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ ......‬وحضــر حلضورهمــا ‪ ......‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي ‪ ........‬وادعتــا املدعيتــان بقولهمــا أن املدعــى‬\n      ‫عليــه هــو والدنــا وقــد عضلنــا عــن الــزواج ويقــوم بــرد اخلطــاب بغيــر ســبب‬\n      ‫وقــد فعــل هــذا مــع أكثــر مــن خاطــب نطلــب رفــع الواليــة عنــه وإعطائهــا‬\n      ‫ألخينــا احلاضــر معنــا هــذه دعوانــا وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫أجــاب قائــا مــن ذكرتــه املدعيتــان مــن أنــي أقــوم بــرد اخلطــاب غيــر‬\n      ‫صحيــح وأنــا ال مانــع عنــدي مــن تزويجهمــا متــى ما تقدم الرجل املناســب‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعيتــن قالــت املدعيــة ‪ ...‬أنــه تقــدم‬\n      ‫لــي يف هــذه الفتــرة وأطلــب تزويجــي منــه وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه قــال ال مانــع عنــدي مــن تزويجهــا بعــد الســؤال عنــه وأطلــب مهلــة‬\n      ‫أســبوعني لذلــك وعليــه قــررت رفــع اجللســة احلمــد هلل وحــده وبعــد فلــدي‬\n      ‫أنــا القاضــي يف احملكمــة العامــة بالريــاض وبنــاء علــى املعاملــة احملالــة‬\n      ‫لنــا مــن فضيلــة رئيــس احملكمــة العامــة ‪/‬املســاعد وتاريــخ‬\n      ‫‪1433/09/06‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/09/06‬ه ـ يف يــوم‬\n      ‫األحــد املوافــق ‪1434/02/17‬ه ـ حضــرت املدعيــة برفقــة املعــرف بهــا‬\n      ‫أخيهــا وحضــر حلضورهــا املدعــى عليــه ولــم حتضــر املدعيــة وبســؤال‬\n      ‫املدعــى عليــه عــن اخلاطــب قــال اتصــل علــي وواعدتــه قبــل يومــن ولــم‬\n      ‫يحضــر وأنــا مــا زلــت أســأل عنــه هكــذا ذكــر بعــد ذلــك جــرى االتصال‬\n      ‫علــى اخلاطــب بالهاتــف مــن قبلنــا فأفــاد بأنــه اتصــل باملدعــى عليــه‬\n      ‫وأخبــره بأنــه سيســأل عنــه ثــم يــرد لــه اخلبــر وانــه لــم يتصــل بــه مــرة‬\n      ‫أخــرى أو يواعــده وقــد مت االتفــاق علــى أن يحضــر اخلاطــب ملنــزل املدعــى‬\n\n\n‫‪103‬‬\n\f‫عليــه هــذا اليــوم بعــد صــاة العصــر ووافــق املدعــى عليــه علــى ذلــك‬\n‫والنتهاء وقت اجللسة جرى رفعها ويف يوم السبت املوافق‪1434/02/23‬هـ‬\n‫حضــرت املدعيتــان املعــرف بهمــا مــن قبــل أخيهمــا ولــم يحضــر املدعــى‬\n‫عليــه رغــم تبلغــه باملوعــد وبســؤالهما عمــا مت قالــت املدعيــة لقــد أخبرنــا‬\n‫اخلاطــب بأنــه ذهــب لوالــدي وتقــدم بخطبتــي وأن والــدي قــام مبحاولــة‬\n‫ثنيــه عــن اخلطبــة وأســاء إلــى ســمعتنا وأننــا هاربــات مــن منزلــه مــن اجــل‬\n‫تركــه للــزواج ولكــن اخلاطــب أصــر علــى اخلطبــة لعلمــه مبــا جــرى‬\n‫واخلاطــب يطلــب أن يتــم النــكاح عنــد طريــق احملكمــة ملــا الحظــه مــن‬\n‫مماطلــة والــدي هكــذا ذكــرت بعــد ذلــك قالــت املدعيــة ‪ ...‬أنــا ســبق‬\n‫وأن تقــدم لــي خطــاب ورفضهــم والــدي بــا ســبب وأطلــب رفــع الواليــة‬\n‫عنــه وجعلهــا ألخــي احلاضــر هكــذا ذكــرت وبســؤال املدعيــة ‪ ...‬ألديــك‬\n‫بينــة علــى ذلــك فقالــت نعــم ومســتعدة بإحضارهــا اجللســة القادمــة بعــد‬\n‫ذلــك أفهمــت املدعيــة ‪ ...‬بإحضــار اخلاطــب ومعــه مشــهد من إمام املســجد‬\n‫مــع شــاهدين يعدلونــه والنتهــاء وقــت اجللســة جــرى رفعهــا ويف يــوم‬\n‫األربعــاء املوافق‪1434/03/04‬ه ـ حضــرت املدعيتــان وكمــا حضــرت‬\n‫‪........‬ســعودية اجلنســية املعــرف بهــن مــن قبــل ‪ ........‬ولــم يحضــر املدعــى‬\n‫عليــه رغــم تبلغــه باملوعــد مبوجــب ورقــة التبليــغ املرفقــة باملعاملــة وقالــت‬\n‫احلاضــرة ‪ ........‬إن والــد بناتــي قــد رفــض تزويجهــن مــن عــدة خطــاب‬\n‫تقدمــوا خلطبتهــن بــدون ســبب بــل ذكــر لــي أنــه ال يريــد تزويجهــن وقــال‬\n‫لــي ال عالقــة لــك بذلــك دون الســؤال عــن اخلطــاب ومــن اخلطــاب وهــو‬\n‫ابــن عمــي وقــد تقــدم البنتــي واآلخــر اســمه ‪........‬وقــد تقــدم وأيضــا تقــدم‬\n‫البنتــي ابــن عمهــا وغيرهــم ممــن ال نعرفهــم وتقدمــوا لوالدهــن مباشــرة‬\n‫وأنــا أطلــب رفــع واليــة التزويــج مــن املدعــى عليــه علــى جميــع بناتــي منــه‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫وهــن التــي تبلــغ مــن العمــر ‪17‬عامــا و ‪ 16‬عامــا و ‪12‬عامــا لئــا يتضــررن‬\n      ‫هكــذا ذكــرت وحضــر يف هــذه اجللســة اخلاطب ‪ ........‬ســعودي اجلنســية‬\n      ‫وقــال باننــي قمــت باالتصــال علــى والــد املدعيــة قبــل شــهر ونصــف‬\n      ‫تقريبــا مــن أجــل خطبــة وقــال ســوف أتصــل بــك إال أنــه لــم يقــم باالتصــال‬\n      ‫بــي فذهبــت إلــى بيــت والــد املدعيــة مــع والــدي وقــد ســأل بعــض األســئلة‬\n      ‫وذكــر لــي بعــض األمــور التــي وقعــت وقــال ســأرد عليكــم إال أنــه لــم‬\n      ‫يتصــل بنــا ولــم يــرد علينــا بشــيء وأبــرز مشــهدا مــن إمــام مســجد واســمه‬\n      ‫‪ ........‬يف ‪1434/3/3‬ه ـ يتضمــن مــا نصــه (نفيدكــم أن األخ يصلــي معنا‬\n      ‫يف حــي ويســكن قــرب مســجدنا) وبطلــب تزكيتــه حضــر للشــهادة‬\n      ‫الشــاهد ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم والشــاهد‬\n      ‫‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬وبســؤالهما‬\n      ‫عــن عمرهمــا وعملهمــا ومقــر ســكنهما وعالقتهمــا بأطــراف الدعــوى‬\n      ‫ا عمــري ‪ 22‬ســنة وأعمــل يف‬       ‫ومــا لديهمــا مــن شــهادة أجــاب األول قائ ـ ً‬\n      ‫وأســكن يف ‪ ........‬حــي‪ ........‬واملدعيــة أختــي واملدعــى عليــه والــدي‬\n      ‫وأشــهد بأنــه بعــد الســؤال عــن اخلاطــب للتحــري عنــه اتضــح أنــه عــدل‬\n      ‫ثقــة صالــح للــزواج مــن أختــي ومماثــل لهــا وأجــاب الثانــي عمــري ‪34‬ســنة‬\n      ‫وأعمــل يف ‪ ........‬وأســكن يف حــي ‪ ........‬واخلاطــب ابــن أخــي وأشــهد بــأن‬\n      ‫اخلاطــب عــدل ثقــة صالــح للــزواج ومحافــظ علــى الصــاة هكــذا شــهدا‬\n      ‫وبســؤال املدعيــة عــن بينتهــا قالــت لــدي شــاهدين همــا أخــي احلاضــر‬\n      ‫وأخــي اآلخــر ســعودي اجلنســية هكــذا ذكــرت وبســؤال الشــاهد عمــا‬\n      ‫لديــه أجــاب قائــا أشــهد بأنــه تقــدم ألختــي وعــدة خطــاب مت رفضهــم‬\n      ‫مــن قبــل والــدي بــا ســبب وبعضهــم مــن أبنــاء العمومــة هكــذا شــهد‬\n      ‫وبســؤال الشــاهد عــن عمــره وعملــه ومقــر ســكنه وعالقتــه بأطــراف‬\n\n\n‫‪105‬‬\n\f‫الدعــوى ومــا لديــه مــن شــهادة أجــاب قائــا عمــري ‪ 27‬ســنة وأعمــل يف‬\n‫‪ ........‬وأســكن يف حــي ‪ ........‬واملدعيــة أختــي واملدعــى عليــه والــدي‬\n‫وأشــهد بأنــه تقــدم ألختــي عــدة خطــاب مت رفضهــم مــن قبــل والــدي بــا‬\n‫ســبب وبعضهــم مــن أبنــاء العمومــة هكــذا شــهد وبســؤال املعــرف عــن‬\n‫موافقتــه علــى واليــة التزويــج فقــال أنــا أوافــق علــى ذلــك مراعــاة‬\n‫للمصلحــة نظــرا لتعــذر اخلطــاب عنــد عقــد النــكاح يف احملكمــة وقبــل‬\n‫إقفــال اجللســة حضــر احملامــي ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ........‬موجــب بطاقــة احملامــاة رقــم ‪ ........‬بصفتــه وكيــا‬\n‫عــن مبوجــب الوكالــة رقــم ‪ ........‬يف ‪1434/2/3‬ه ـ الصادرة من كتابة‬\n‫العــدل الثانيــة بجنــوب ‪ ........‬والتــي تخولــه حــق املطالبــة واملرافعــة الــخ‬\n‫وبســؤاله عمــا لديــه أجــاب قائــا أنــا لــم أطلــع علــى املعاملــة وأطلــب‬\n‫تزويــدي بصــورة مــن الضبــط كمــا أطلــب تزويــدي برقــم الســجل املدني‬\n‫للخاطــب ومهلــة لكــي يتمكــن موكلــي مــن الســؤال عنــه هكــذا‬\n‫فجــرى إفهامــه بــأن موكلــه علــى علــم بالدعــوى واخلاطــب منــذ بدايــة‬\n‫الدعــوى واتصــال اخلاطــب بــه قبــل شــهر ونصــف تقريبــا وحضــوره لبيتــه‬\n‫فقــال االتصــال ال يكفــي هكــذا ذكــر وجــرى تزويــد املدعــى عليــه‬\n‫وكالــة بصــورة مــن الضبــط وبعــرض شــهادة الشــاهدين علــى املدعــى‬\n‫عليــه وكالــة قــال ال أعرفهــم وســأعرض الشــهادة علــى موكلي هكذا‬\n‫ذكــر والنتهــاء وقــت اجللســة جــرى رفعهــا ويف يــوم األحــد‬\n‫املوافق‪1434/03/08‬ه ـ حضــرت املدعيتــان املعــرف بهمــا مــن قبــل‬\n‫أخيهمــا ولــم يحضــر املدعــى عليــه أو مــن ينــوب عنــه علــى الرغــم مــن‬\n‫تبلــغ وكيلــه مبوعــد هــذه اجللســة كمــا هــو مثبــت يف ضبــط اجللســة‬\n‫الســابقة وبســؤال املدعيــن عــن عمريهمــا فقالــت ‪ ........‬عمــري اثنــان‬\n\n\n                                                                                       ‫‪106‬‬\n\f      ‫وعشــرون ســنة وقالــت ‪ ........‬عمــري اثنــان وثالثــون ســنة وقــد أفــاد‬\n      ‫املدعــى عليــه وكالــة يف اجللســة الســابقة عنــد ســؤاله عــن موكلــه فقــال‬\n      ‫بــأن موكلــه خــارج اململكــة يف هــذا الوقــت بعــد ذلــك أفهمــت املدعيتني‬\n      ‫بإحضــار مزكيــن للشــاهدين وإحضــار مزكيــن ألخيهمــا الــذي‬\n      ‫يرغبــان يف إقامتــه وليــا عليهمــا ولــذا جــرى رفــع اجللســة و يف يــوم األربعاء‬\n      ‫املوافق‪1434/03/11‬ه ـ حضــرت املدعيتــان برفقــة املعرف بهما أخيهما‬\n      ‫‪ ...‬ولــم يحضــر املدعــى عليــه وقــد حضــر يــوم االثنــن ‪1434/3/9‬ه ـ‬\n      ‫وجــرى إفهامــه شــفهيا مبوعــد هــذه اجللســة وبســؤال املدعيتــن عــن‬\n      ‫املزكــن للشــاهدين وأخيهــن احلاضــر الــذي يرغبــان إقامتــه وليــا فقالتــا‬\n      ‫الشــهود حضــروا ونطلــب ســماع شــهادتهم وأحضــرن للشــهادة كال مــن‬\n      ‫‪ ........‬ســعودي اجلنســية و‪ ........‬ســعودي اجلنســية مبوجب الســجل املدني‬\n      ‫رقــم‪ ........‬وبســؤال الشــاهدين عــن عمرهمــا وعملهمــا ومقــر ســكنهما‬\n      ‫وعالقتهمــا بأطــراف الدعــوى ومــا لديهمــا مــن شــهادة أجــاب األول قائال‬\n      ‫عمــري ‪43‬ســنة وأعمــل يف‪ ........‬وأســكن يف حــي‪ ........‬واملدعيتــان هــم‬\n      ‫أوالد عمومــه مــن بعيــد وأجــاب الثانــي عمــري ‪38‬ســنة وأعمــل يف‪........‬‬\n      ‫وأســكن يف حــي‪ ........‬واملدعيتــان هــم أوالد عمومــه مــن بعيــد وشــهد‬\n      ‫كل واحــد منهمــا مبفــرده بعدالــة وثقــة كال مــن احلاضر هكذا شــهدا‬\n      ‫وقــال املزكــي أنــا ســبق أن عرضــت علــى والــد املدعيتــن أحــد اخلطــاب‬\n      ‫يعمــل مــدرس ومشــهود لــه بالعدالــة خلطبــة ابنتــه ‪ ...‬ولكنــه رفــض ذلــك‬\n      ‫دون ســبب واضــح وقــال لــي أنــه لــن يــزوج اآلن وكان ذلــك قبــل ثــاث‬\n      ‫ســنوات تقريبـ ًا هكــذا ذكــر وملزيــد تأمــل جــرى رفــع اجللســة ويف يــوم‬\n      ‫األحــد املوافــق ‪1434/03/15‬ه ـ حضــرت املدعيتــان برفقــة املعــرف‬\n      ‫بهمــا احلاضــر يف اجللســات الســابقة واملدعــى عليــه وبســؤال املدعــى عليــه‬\n\n\n‫‪107‬‬\n\f‫عــن اخلاطــب فقــال لقــد ســألت عنــه وهــو صالــح للــزواج مــن ابنتــي وال‬\n‫مانــع لــدي مــن تزويجــه بالشــروط التاليــة إحضــار تعريــف بالراتــب مــع‬\n‫جتهيــز بيــت كامــل مســتقل يليــق بهــا وذلــك قبــل العقــد وإحضار شــهادة‬\n‫مــن إمــام مســجد و يدفــع مهــر قــدره خمســون ألــف ريــال و مؤخــر قــدره‬\n‫خمســون ألــف ريــال بشــيك مصــدق وإال يكــون عليــه التزامــات ماليــة‬\n‫لئــا ينعكــس علــى احليــاة األســرية ســلبا مســتقبال هــذه شــروطي‬\n‫وبعــرض ذلــك علــى املدعيــة قالــت املهــر مت االتفــاق مــع اخلاطــب علــى ان‬\n‫يكــون قــدره أربعــون ألــف ريــال بــدون مؤخــر ولــن يقبــل اخلاطــب بهــذا‬\n‫املبلــغ وكذلــك ال حاجــة للمؤخــر وأمــا املنــزل فلديــه دور مســتقل يف‬\n‫منــزل والــده هكــذا ذكــرت وبعــرض ذلــك علــى املدعــى عليــه فقــال أنــا‬\n‫لــن أوافــق إال بشــروطي هكــذا ذكــر بعــد ذلــك قالــت املدعيــة أختــي‬\n‫الكبــرى تزوجــت علــى مهــر قــدره ثالثــون ألــف ريــال بــدون مؤخــر‬\n‫هكــذا ذكــرت وبعــرض ذلــك علــى املدعــى عليــه قــال هــذا يخصنــي‬\n‫كمــا أن ابنتــي كانــت كبيــرة يف الســن إذ كان عمرهــا عنــد الــزواج‬\n‫‪ 35‬ســنة هكــذا ذكــر بعــد ذلــك قــام املدعــى عليــه بالدعــاء علــى أوالده‬\n‫وســبهم فجــرى نهــره عــن ذلــك فبنــاء علــى مــا تقــدم وملــا جــاء يف شــهادة‬\n‫الشــاهدين املعدلــن حســب األصــول الشــرعية املتضمنــة عضــل املدعــى‬\n‫عليــه البنتيــه ومبــا أن النــكاح حــق للمــرأة وال يجــوز لوليهــا منعهــا منــه‬\n     ‫ن مِ ــنْ عِ َباد ُ‬\n‫ِكـ ْـم‬                   ‫الص ِ ِ‬\n                       ‫الـ َ‬             ‫امــى مِ ْن ُ‬\n                              ‫كـ ْـم َو َّ‬               ‫ك ُحــوا ْ َ‬\n                                                    ‫ال َي َ‬         ‫تعالى‪((:‬و َأ ْن ِ‬\n                                                                            ‫َ‬         ‫قــال اهلل‬\n‫ِكـ ْـم)) النــور‪ ،32:‬جــاء يف املغنــي البــن قدامــة (ومعنــى العضــل منــع‬          ‫َو ِإ َمائ ُ‬\n‫املــرأة مــن التزويــج بكفئهــا إذا طلبــت ذلــك ورغــب كل واحــد منهمــا يف‬\n‫صاحبه‪،‬وســواء طلبــت التزويــج مبهــر مثلهــا أو دونه وبهذا قال الشــافعي‬\n‫و ‪،‬وقــال أبــو حنيفــة لهــم منعهــا مــن التزويــج بــدون مهــر مثلهــا ألن عليهــم‬\n\n\n                                                                                                      ‫‪108‬‬\n\f      ‫يف ذلــك عــارا وفيــه ضــررا علــى نســائها لنقــص مهــر مثلهــن ولنــا أن املهــر‬\n      ‫خالــص حقهــا وعــوض يختــص بهــا فلــم يكــن لهــم االعتــراض عليهــا‬\n      ‫فيــه كثمــن عبدهــا وأجــرة دارهــا وألنهــا لــو أســقطته بعــد وجوبــه ســقط‬\n      ‫كلــه فبعضــه أولى‪،‬فــإن رغبــت يف كــفء بعينــه وأرادت زويجهــا لغيــره‬\n      ‫مــن أكفائهــا وامتنــع مــن تزويجهــا مــن الــذي أرادتــه كان عاضــا لهــا‬\n      ‫فأمــا إن طلبــت التزويــج بغيــر كفئهــا فلــه منعهــا مــن ذلــك وال يكــون‬\n      ‫عاضــا لهــا بهــذا)‪ ،‬الرســول صلــى اهلل عليــه وســلم حيــث قــال ‪ ( :‬إذا‬\n      ‫أتاكــم مــن ترضــون دينــه وخلقــه فأنكحــوه إال تفعلــوا تكــن فتنــة يف‬\n      ‫األرض وفســاد كبيــر)‪ .‬أخرجــه الترمــذي يف ســننه ‪ ،‬كتــاب النــكاح‪،‬‬\n      ‫بــاب مــا جــاء إذا جاءكــم مــن ترضــون دينــه فزوجــوه وذكــره األلبانــي‬\n      ‫يف إرواء الغليــل وحســنه وملــا يف العضــل مــن أضــرار جليــة وظاهــرة قــال‬\n      ‫املباركفــوري صاحــب حتفــة األحــوذي « فســاد عريــض ‪ :‬أي ذو عــرض‬\n      ‫‪ ،‬أي كبير؛وذلــك ألنكــم إن لــم تزوجوهــا إال مــن ذي مــال أو جــاه ‪،‬‬\n      ‫رمبــا يبقــى أكثــر نســائكم بــا زواج ‪ ،‬وأكثــر رجالكــم بــا نســاء ‪،‬‬\n      ‫فيثكــر االفتتــان بالزنــا‪ ،‬ورمبــا يلحــق األوليــاء عــار فتهيــج الفــن‬\n      ‫والفســاد ‪ ،‬ويترتــب عليــه قطــع النســب ‪ ،‬وقلــة الصــاح والعفــة» و منــع‬\n      ‫الولــي موليتــه مــن النــكاح بكــفء رغبتــه ضــرر بــن ‪ ،‬وإضــرار بحــق‬\n      ‫املــرأة املشــروع مــن العفــاف بالنــكاح ‪ ،‬والضــرر جــاءت الشــريعة مبنعــه‬\n      ‫ورفعــه‪ ،‬والعاضــل تــزول واليتــه بامتناعــه لرفــع الضــرر عــن موليتــه و قــد‬\n      ‫ذكــر جمــع مــن العلمــاء إجمــاع أهــل العلــم واتفاقهــم علــى حتــرمي العضــل‬\n      ‫يف النــكاح ‪ .‬وقــال ابــن رشــد ‪ -‬رحمــه اهلل ‪ : -‬واتفقــوا علــى أنــه ليــس‬\n      ‫للولــي أن يعضــل موليتــه إذا دعــت إلــى كــفء‪ ،‬وبصــداق مثلهــا» وقــال‪:‬‬\n      ‫ال ضرر وال ضرار وقال ابن تيمية ‪ -‬رحمه اهلل ‪ : -‬يف مجموع الفتاوى‪،‬‬\n\n\n‫‪109‬‬\n\f‫فليــس للولــي أن يجبرهــا علــى نــكاح مــن ال ترضــاه ‪ ،‬وال يعضلهــا عــن‬\n‫نــكاح مــن ترضــاه ‪ ،‬إذا كان كفئ ـ ًا باتفــاق األئمــة‪ ،‬وإمنــا يجبرهــا‬\n‫ويعضلهــا أهــل اجلاهليــة ‪ ،‬والظلمــة ؟ ومبــا أن املتقــدم خلطبــة املدعيــة‪...‬‬\n‫عــدل مكافــئ بإقــرار املدعــى عليــه وامتنــع املدعــى عليــه مــن تزويجهــا‬\n‫بســبب شــروطه التــي ال حــق لــه فيهــا ممــا يســتدل منــه علــى عضلــه ‪.‬ومبــا‬\n‫أن انتقــال الواليــة للحاكــم الشــرعي أو الولــي األقــرب فيهــا خــاف بــن‬\n‫أهــل العلــم واملذهــب عنــد احلنابلــة أنــه إذا عضــل الولــي األقــرب انتقلــت‬\n‫الواليــة إلــى الولــي األبعــد ‪ ،‬نــص عليــه أحمــد ‪ ،‬ألنــه تعــذر التزويــج مــن‬\n‫لوجـ ّـن ‪ ،‬وألنــه يفســق بالعضــل‬ ‫جهــة األقــرب فملكــه األبعــد كمــا ُ‬\n‫فتنتقــل الواليــة عنــه ‪ ،‬فــإن عضــل األوليــاء كلهــم زوج احلاكــم ‪ ،‬وردوا‬\n‫علــى االســتدالل بقــول النبــي صلــى اهلل عليــه وســلم ‪ « :‬الســلطان ولــي‬\n‫مــن ال ولــي لــه» أنــه يحمــل علــى مــا إذا عضــل الــكل ‪ ،‬ألن قولــه ‪« :‬فــإن‬\n‫اشــتجروا ‪ »...‬ضميــر جمــع يتنــاول الكلجــاء يف كشــاف القنــاع (أو‬\n‫عضــل األقــرب زوج األبعــد يعنــي مــن يلــي األقــرب من األوليــاء ألن الوالية‬\n‫ال تثبــت لألقــرب مــع اتصافــه مبــا تقــدم فوجــوده كعدمــه ولتعــذر‬\n‫التزويــج مــن جهــة األقــرب بالعضــل جعــل كالعــدم كمــا لوجــن فــإن‬\n‫عضــل األبعــد أيضــا زوجهــا احلاكــم لقولــه صلــى اهلل عليــه وســلم فــإن‬\n‫اشــتجروا فالســلطان ولــي مــن ال ولــي لهــا والعضــل منعهــا أن تتــزوج‬\n‫بكــفء إذا طلبــت ذلــك ورغــب كل منهمــا يف صاحبــه مبــا صــح مهــرا‬\n‫ولــوكان بــدون مهــر مثلهــا قالــه الشــيخ ومــن صــور العضــل املســقط‬\n‫لواليتــه إذا امتنــع اخلطــاب لشــدة الولــي) ومبــا أن املصلحــة والسياســة‬\n‫الشــرعية تقتضــي توليــة األقــرب يف هــذه القضيــة نظــر التعــدد املدعيــات‬\n‫وعــدم وجــود اخلطــاب حاليــا ألغلبهــن وامتنــاع اخلطــاب مــن التــزوج عــن‬\n\n\n                                                                                       ‫‪110‬‬\n\f      ‫طريــق احملاكــم يف الغالــب ومبــا ان والــدة املدعيتــن وبقيــة بنات املدعى‬\n      ‫عليــه قــد تقدمــت بطلــب شــمول بقيــة البنــات برفــع واليــة األب ومبــا أنــه‬\n      ‫قــد ثبــت عضــل املدعــى البنتيــه املدعيتــن فيقــاس عليهــن بقيــة بناتــه‬\n      ‫وهــن الشــقيقات للمدعيتــن وهــن ‪ ...‬و‪ ...‬و‪ ...‬وقــد ذكــر الفقهــاء مــن‬\n      ‫صــور العضــل إذا امتنــع اخلطــاب مــن خطبــة املــرأة لشــدة الولــي واخلــوف‬\n      ‫ا حينئــذ وآثماً‪ ،‬ويرفع أمــره للحاكم ويزوجها‬          ‫منــه ‪ ،‬فإنــه يعتبــر عاضـ ً‬\n      ‫إذا ثبــت عضــل وليهــا لهــا وال شــك أن عضــل األب بنتيــه مدعــاة المتنــاع‬\n      ‫اخلطــاب مــن اخلطبــة مســتقبال لبقيــة البنــات بســبب تعنــت األب وامتناعــه‬\n      ‫بــا ســبب كمــا أن املصلحــة الشــرعية والسياســة الشــرعية تقتضــي‬\n      ‫رفــع واليــة التزويــج مــن املدعــى عليــه لبناتــه حتقيقــا ملصلحتهــن مــن‬\n      ‫امتنــاع املدعــى عليــه مــن تزويجهــن مســتقبال أســوة بأخواتهــن وال يخفــى‬\n      ‫مــا تســتدعيه مثــل هــذه القضايــا مــن إجــراءات قــد تنفــر اخلطــاب‬\n      ‫مســتقبال وقــد نــص الفقهــاء علــى فســق الولــي العاضــل علــى خــاف‬\n      ‫بينهــم يف اشــتراط عــدد مــرات العضــل جلميــع مــا تقــدم فقــد ثبــت لــدي‬\n      ‫عضــل املدعــى عليــه البنتيــه وجعلــت واليــة التزويــج جلميــع البنــات وهــن‬\n      ‫ألخيهــن وبذلــك حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر عــدم‬\n      ‫قناعتــه باحلكــم وطالــب بتدقيــق احلكــم واســتعد بتقــدمي الئحــة‬\n      ‫اعتراضيــة وأفهــم بأنــه لــه مــدة قدرهــا ثالثــون يــوم لتقــدمي اعتراضــه‬\n      ‫اعتبــارا مــن تاريــخ اســتالم صــورة مــن نســخة احلكــم وإذا مضــت املــدة‬\n      ‫احملــددة لالعتــراض ولــم يقــدم الئحتــه فيهــا ســقط حقــه يف االســتئناف‬\n      ‫واكتســب احلكــم القطعيــة وحــدد موعــد تســليم صــورة نســخة احلكــم‬\n      ‫هــذا اليــوم الســاعة الثانيــة ظهــرا ومت إقفــال اجللســة الســاعة التاســعة‬\n      ‫والنصــف وبــاهلل التوفيــق ‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n\n\n‫‪111‬‬\n\f                                    ‫وصحبه وسلم ‪ .‬حرر يف ‪ 1434/03/15‬هـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة وبنــاء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامة‪/‬املســاعد‬\n‫وتاريــخ ‪1433/09/06‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/09/06‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق ‪ 1434/05/28‬ه ـ حيــث عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار املــدون علــى ظهــر الصــك‬\n‫واملتضمــن مــا نصــه (املصادقــة علــى احلكــم واهلل املوفــق قاضــي‬\n‫اســتئناف ختمــه وتوقيعــه قاضــي اســتئناف ختمــه وتوقيعــه رئيــس‬\n‫الدائــرة ختمــه وتوقيعــه) وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/28‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬املالزم القضائي لدى الشــيخ‪........‬‬\n‫القاضــي يف احملكمــة العامــة‪ ........‬بنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة العامــة وتاريــخ ‪1433/09/06‬ه ـ املقيــدة‬\n‫باحملكمــة وتاريــخ ‪1433/09/06‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n‫‪1434/09/15‬ه ـ وردتنــا املعاملــة مــن محكمــة االســتئناف وتاريــخ‬\n‫‪1434/8/14‬ه ـ املرفــق بهــا قــرار االلتمــاس رقــم وتاريــخ ‪1434/8/2‬ه ـ‬\n‫واملتضمــن مــا نصــه بعــد املقدمــة‪« :‬بنــاء علــى االلتمــاس املقــدم لفضيلــة‬\n‫رئيــس محكمــة االســتئناف بالريــاض املســاعد املقيــد يف باحملكمــة‬\n‫برقــم‪ ........‬وتاريــخ ‪1434/7/25‬ه ـ املتعلــق بطلبــه إعــادة النظــر يف‬\n‫احلكــم الصــادر بــه الصــك وتاريــخ ‪1434/3/15‬ه ـ مــن فضيلــة القاضي‬\n‫باحملكمــة العامــة بالريــاض الشــيخ‪ .......‬وبنــاء علــى املادتــن رقــم ‪192‬‬\n‫و‪ 194‬مــن نظــام املرافعــات فقــد مت االطــاع علــى االلتمــاس املذكــور‬\n‫وعلــى كافــة األوراق املرفقــة وتقــرر الدائــرة عــدم قبــول االلتمــاس لعــدم‬\n\n\n                                                                                      ‫‪112‬‬\n\f      ‫انطبــاق التعليمــات بحقــه‪ ،‬قاضــي اســتئناف ‪ ...‬توقيــع وختــم ‪ ،‬قاضــي‬\n      ‫اســتئناف ‪ ...‬توقيــع وختــم‪ ،‬رئيــس الدائــرة ‪ ...‬توقيــع وختــم» أ‪.‬ه ـ وحتــى‬\n      ‫ال يخفــى جــرى حتريــره وإحلاقــه‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/15‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫املختصــة بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n      ‫االســتئناف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد وتاريــخ ‪1434/4/14‬ه ـ املرفــق بهــا الصــك الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ........‬وتاريــخ ‪1434/3/15‬ه ـ‬\n      ‫اخلــاص بدعــوى‪ ...‬ضــد والدهــا‪ ......‬ضــد‪ ........‬والدهمــا بشــأن عضــل‬\n      ‫ولــي وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة‬\n      ‫تقــرر الدائــرة املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                                  ‫محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪113‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"95425f3c-f21e-5113-8fb9-4b19592afd57","source_page_start":100,"source_page_end":113,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"15a510ea582ad037c451d0c7855cfd37acc2247a215e1cb4217db267a67d8e0e","normalized_text_hash":"5cd82995bfb72ca4aa5e33d8c3dab5c6e6ff7530cd8cca79f9e553a8b81af740","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v11-p100-3462992"},{"id":"e32ce27b-7c5f-5ef3-91e3-87983fdda516","document_type":"judgment","category":"judicial","subcategory":"general","title":"عضل -والية -مطالبة بنت بإلزام والدها بتزويجها أو احلكم بعضله وجعل واليتها للحاكم الشرعي -املدعية تقيم يف دار الرعاية االجتماعية لتعرضها للعنف األسري -أنكر املدعى عليه العضل وطلب السؤال عن اخلاطب -ماطل املدعى عليه وقدح بأن اخلاطب أجنبي -البينة بشهادة الشهود بصالحية وكفء اخلاطب -ثبت لدى المحكمة صالحية اخلاطب ورفعا للضرر عن املدعية وخوفا من تنازع األولياء رفعت المحكمة والية األب وجعلتها","document_number":"34282151","case_number":"34260520","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/29","year":"1434","subject":"عضل -والية -مطالبة بنت بإلزام والدها بتزويجها أو احلكم بعضله وجعل واليتها للحاكم الشرعي -املدعية تقيم يف دار الرعاية االجتماعية لتعرضها للعنف األسري -أنكر املدعى عليه العضل وطلب السؤال عن اخلاطب -ماطل املدعى عليه وقدح بأن اخلاطب أجنبي -البينة بشهادة الشهود بصالحية وكفء اخلاطب -ثبت لدى المحكمة صالحية اخلاطب ورفعا للضرر عن املدعية وخوفا من تنازع األولياء رفعت المحكمة والية األب وجعلتها","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/7/29 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34282151 :‬‬\n                   ‫َر ْق ُم الدعوى‪34260520 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34368518‬تاريخه‪1434/11/24:‬هـ‬\n\n\n‫عضــل ‪ -‬واليــة ‪ -‬مطالبــة بنــت بإلــزام والدهــا بتزويجهــا أو احلكــم‬\n‫بعضلــه وجعــل واليتهــا للحاكــم الشــرعي ‪ -‬املدعيــة تقيــم يف دار‬\n‫الرعايــة االجتماعيــة لتعرضهــا للعنــف األســري ‪ -‬أنكــر املدعــى عليــه‬\n‫العضــل وطلــب الســؤال عــن اخلاطــب ‪ -‬ماطــل املدعــى عليــه وقــدح‬\n‫بــأن اخلاطــب أجنبــي ‪ -‬البينــة بشــهادة الشــهود بصالحيــة وكــفء‬\n‫اخلاطــب ‪ -‬ثبــت لــدى احملكمــة صالحيــة اخلاطــب ورفعــا للضــرر عــن‬\n‫املدعيــة وخوفــا مــن تنــازع األوليــاء رفعــت احملكمــة واليــة األب وجعلتهــا‬\n                                                         ‫للحاكــم الشــرعي‪.‬‬\n\n\n\n                ‫‪ .1‬قول الرسول صلى اهلل عليه وسلم (ال ضرر وال ضرار)‬\n‫‪ .2‬قــول العلمــاء (إن الولــي األقــرب إذا عضــل موليتــه انتقلــت الواليــة‬\n                                                              ‫إلــى الســلطان)‬\n‫‪ .3‬مــا اســتند إليــه القاضــي مــن مبــادئ عامــة وقواعــد العدالــة الــواردة‬\n                                                                   ‫يف احلكــم‪.‬‬\n\n\n\n‫أدعــت بنــت علــى والدهــا تطلــب إلزامــه بتزويجهــا أو احلكــم بعضلــه‬\n‫وتزويــج احملكمــة لهــا باملتقــدم خلطبتهــا وذكــرت أنهــا تقيــم يف دار‬\n‫الرعايــة االجتماعيــة يف ‪ ........‬لتعرضهــا لإلســاءة والعنــف األســري‬\n                                                                                    ‫‪114‬‬\n\f      ‫مــن والديهــا‪ ،‬أنكــر املدعــى عليــه العضــل وطلــب مهلــة للســؤال عــن‬\n      ‫اخلاطــب وكان اخلاطــب حاضــر ًا يف اجللســة واســتعد بتزويــد املدعــى‬\n      ‫عليــه بــكل مــا يريــد وقــدم ورقــة تتضمــن معلومــات عــن عملــه ومقــر‬\n      ‫ســكنه وهاتــف بعــض أقاربــه وأصحابــه‪ ،‬طلــب املدعــى عليه مهلة شــهر‬\n      ‫للبحــث والتحــري‪ ،‬ثــم حضــر املدعــى عليــه وقــرر أنــه لــم يجــد أحــد ًا‬\n      ‫يعــرف اخلاطــب وأنــه رجــل أجنبــي فهــو مينــي اجلنســية‪ ،‬وقالــت املدعيــة‬\n      ‫إن مــا ذكــره املدعــى عليــه مــن ســوء أخــاق اخلاطــب غيــر صحيــح وال‬\n      ‫دليــل عليــه وأنــي قــد رضيتــه وهــو مناســب لــي وال يوجــد مــا مينــع مــن‬\n      ‫زواجــي بــه ولــم يتقــدم لــي ســواه وذكــرت أنــه قــد صــدرت موافقــة‬\n      ‫وزارة الداخليــة علــى زواجهــا باألجنبــي مبوجــب خطــاب رســمي كمــا‬\n      ‫أثبــت التقريــر الطبــي ســامة املدعيــة واخلاطــب مــن األمــراض املعديــة‬\n      ‫جــرى اطــاع احملكمــة عليهــا وإثباتهــا‪ ،‬كمــا أن املدعيــة ذكــرت أن‬\n      ‫والدهــا تــزوج بامــرأة أجنبيــة وصــادق املدعــى عليــه علــى ذلــك وألنــه ال‬\n      ‫يوجــد مــا مينــع مــن تزويــج املــرأة باخلاطــب وحاجــة املــرأة للــزواج وألن‬\n      ‫الــزواج مــن األجانــب يف أســرتها موجــود وملوافقــة وزارة الداخليــة علــى‬\n      ‫الــزواج بــن املدعيــة وخاطبهــا وألن العضــل هــو أن مينــع الولــي موليتــه مــن‬\n      ‫الــزواج بالكــفء الــذي ترضــاه واختــاف اجلنســية ال يكــون مانع ـاً‪،‬‬\n      ‫ورفع ـ ًا للضــرر عــن املدعيــة لقولــه صلــى اهلل عليــه وســلم (ال ضــرر وال‬\n      ‫ضــرار) وألن القــول املختــار أن الولــي إذا عضــل موليتــه انتقلــت الواليــة‬\n      ‫إلــى الســلطان ولــدرء املفســدة الناشــئة مــن تنــازع األوليــاء واختالفهــم‬\n      ‫أثبتــت احملكمــة عضــل املدعــى عليــه البنتــه وفســخت واليتــه عنهــا‬\n      ‫وجعلــت واليــة التزويــج للحاكــم الشــرعي‪ ،‬اعتــرض املدعــى عليــه وبعــد‬\n      ‫مخابــرة مــع محكمــة االســتئناف لطلــب البينــة علــى أن اخلاطــب كــفء‬\n\n\n‫‪115‬‬\n\f‫للمدعيــة املخطوبــة يف الديــن واخللــق أحضــرت املدعيــة للمحكمــة‬\n‫شــاهدين شــهدا بــأن اخلاطــب كــفء للمدعيــة يف الديــن واخللــق وجــرى‬\n                                      ‫تعديــل الشــاهدين‪ ،‬صــدق احلكــم‬\n\n\n\n\n‫العامــة‬\n     ‫ّ‬   ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬مســاعد رئيــس احملكمــة‬\n‫العامــة‬\n       ‫َ‬  ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫وتاريــخ ‪1434/06/06‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1434/06/06‬ه‬\n‫ففــي يــوم الثالثــاء املوافــق‪ 1434/06/20‬ه ـ افتتحت اجللســة الســاعة ‪30‬‬\n‫‪09 :‬وفيهــا حضــرت (‪ ).....‬ســعودية اجلنســية برفقــه املشــرفة االجتماعيــة‬\n‫بــدار احلمايــة االجتماعيــة باملنطقــة الشــرقية (‪ ).....‬ســعودية اجلنســية‬\n‫ولــم يحضــر املدعــى عليــه وال مــن ينــوب عنــه رغــم تبلغــه مبوعــد اجللســة‬\n‫شــخصي ًا حســب ورقــة التبليــغ الــواردة لنــا مــن قســم محضــري اخلصــوم‬\n‫باحملكمــة يف ‪1434/6/13‬ه ـ وعليــه رفعــت اجللســة إلــى يــوم األحــد‬\n‫املوافــق ‪1434/6/25‬ه ـ الســاعة التاســعة والنصــف صباح ـ ًا وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                           ‫يف ‪1434/06/20‬هــ‪.‬‬\n‫العامــة‬\n   ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬مســاعد رئيــس احملكمــة‬\n‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫العامــة‪ ........‬وتاريــخ ‪1434/06/06‬ه املقيــدة باحملكمــة‬      ‫َ‬     ‫احملكمــة‬\n‫وتاريــخ ‪ 1434/06/06‬ه ـ ففــي يــوم األحــد املوافــق ‪1434/06/25‬ه ـ‬\n‫افتتحــت اجللســة الســاعة وفيهــا حضــرت (‪ ).....‬ســعودية اجلنســية برفقــه‬\n‫املشــرفة االجتماعيــة بــدار احلمايــة االجتماعيــة باملنطقــة الشــرقية (‪).....‬‬\n\n                                                                                    ‫‪116‬‬\n\f      ‫ســعودية اجلنســية وادعــت علــى احلاضــر معهــا (‪ ).....‬ســعودي الوكيــل‬\n      ‫الشــرعي عــن (‪ ).....‬ســعودي بالوكالــة الصــادرة مــن كتابــة عــدل يف‬\n      ‫‪1432/10/9‬ه قائلـ ًة يف دعواهــا عليــه تقــدم خلطبتــي املدعــو (‪ ).....‬مينــي‬\n      ‫اجلنســية ويقيــم يف اململكــة العربيــة الســعودية وقــد رضيــت بــه وهــو‬\n      ‫مكافــئ ومناســب لــي إال أن والــدي يرفــض تزويجــي منــه أطلــب إلــزام‬\n      ‫والــدي بعقــد نكاحــي عليــه أو احلكــم بعضلــه لــي وتزويجــي باملتقــدم‬\n      ‫خلطبتــي عــن طريــق احملكمــة علم ـ ًا أن والــدي قــد امتنــع مــن تزويــج‬\n      ‫أخواتــي (‪ ).....‬و(‪ ).....‬و(‪ ).....‬وأنــا اآلن أقيــم يف دار احلمايــة بــ‪........‬‬\n      ‫لتعرضــي لإلســاءة والعنــف مــن والــدي ووالدتــي هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه وكالــة قــال أطلــب مهلــة ملراجعــة موكلــي وســماع مــا لديه‬\n      ‫فطلبــت مــن املدعــى عليــه وكالــة إحضــار موكلــه شــخصي ًا يف اجللســة‬\n      ‫القادمــة ويف جلســة أخــرى حضــرت املدعيــة برفقــة املشــرفة االجتماعيــة‬\n      ‫املــدون هويتهــا يف اجللســة املاضيــة وحضــر حلضورها املدعــى عليه أصالة‬\n      ‫والدهــا (‪ ).....‬ســعودي اجلنســية بالســجل رقــم (‪ ).....‬كمــا حضــر يف‬\n      ‫اجللســة املدعــو(‪ ).....‬مينــي اجلنســية خاطــب املــرأة املدعيــة وجــرى عــرض‬\n      ‫دعــوى املدعيــة علــى والدهــا املدعــى عليــه فقــال إننــي لــم اعضــل ابنتــي‬\n      ‫املدعيــة عــن الــزواج ولكننــي اشــترط يف اخلاطــب أن يكــون كفئ ـ ًا‬\n      ‫وبالنســبة للمتقــدم خلطبــة ابنتــي فإننــي اطلــب مهلــة للســؤال عنــه وعــن‬\n      ‫وظيفتــه وأخالقــه ومتــى مــا كان مناســب ًا البنتــي فــا مانــع عنــدي مــن‬\n      ‫تزويجهــا بــه وقــال اخلاطــب اننــي مســتعد بتزويــد والــد املدعيــة بــكل مــا‬\n      ‫يريــد عنــي مــن معلومــات هكــذا قــرر وقــد جــرى تزويــد املدعــى عليــه‬\n      ‫بورقــة تتضمــن معلومــات عــن اخلاطــب وعملــة ومقــر ســكنه وهاتــف‬\n      ‫بعــض اقاربــه واصحابــه ورقــم جوالــه وقــال املدعــى عليــه اطلــب مهلة ملدة‬\n\n\n‫‪117‬‬\n\f‫شــهر للبحــث والتحــري عــن اخلاطــب ويف جلســة أخــرى حضــرت املدعيــة‬\n‫واملشــرفة االجتماعيــة وحضــر حلضورهــا املدعــى عليــه أصالــة والــد‬\n‫املدعيــة ووكيلــه (‪ ).....‬وقــال املدعــى عليــه لقــد ســألت عــن اخلاطــب ولــم‬\n‫أجــد أحــد ًا يعرفــه كمــا لــم أجد أي معلومات للمؤسســة التي يعمل فيها‬\n‫ولــم يعطينــي رقــم املؤسســة الثابــت وقــد حضــر يف اجللســة اخلاطــب (‪).....‬‬\n‫املــدون هويتــه يف اجللســة املاضيــة وقــال لقــد زودت املدعــى عليــه بأرقــام‬\n‫أقــارب لــي وأرقــام مديــري يف العمــل ولــم يحصــل مــن املدعــى عليــه أي‬\n‫اتصــال أو ســؤال ومــا ذكــره غيــر صحيــح فجــرى ســؤال املدعــى عليــه‬\n‫هــل لديــك أســباب وجيهــة يف االمتنــاع عــن التزويــج فقــال إننــي أرفــض‬\n‫تزويــج املدعيــة مــن خاطبهــا لســوء أخالقــه وعــدم مراعاتــه للعــادات‬\n‫والتقاليــد حيــث لــم يــأت البيــوت مــن أبوابهــا ولــم يخطــب ابنتــي منــي‬\n‫وكذلــك عــدم كفاءتــه املعتبــرة للمدعيــة فهــو أجنبــي وهــي ســعودية‬\n‫واملدعيــة لــم يتقــدم خلطبتهــا أحــد قبــل هــذا اخلاطــب لصغــر ســنها فــا‬\n‫يوجــد عضــل منــي كمــا أن زواج املدعيــة باخلاطــب ســبب لقطــع الرحــم‬\n‫بينهــا وبينــي وبينهــا وأهلهــا لــذا فإننــي أطلــب رد دعــوى العضــل املقدمــة‬\n‫مــن إبنتــي املدعيــة هــذا مــا لــدي وبعرضــه علــى املدعيــة قالــت مــا ذكــره‬\n‫مــن ســوء خلــق اخلاطــب فهــذا غيــر صحيــح وال دليــل للمدعــى عليــه علــى‬\n‫ذلــك وأمــا عــدم تقدمــه لــي يف منــزل والــدي فهــو بســبب أننــي أقيــم يف‬\n‫دار احلمايــة منــذ ســنتني وأمــا عــدم الكفــاءة بينــي وبــن اخلاطــب فهــو‬\n‫غيــر صحيــح واجلنســية ال عالقــة لهــا بالكفــاءة وهــو كفــؤ لي ومناســب‬\n‫لــي يف الديــن واخللــق وقــد رضيتــه وال يوجــد مــا مينــع مــن زواجــي بــه وأمــا‬\n‫أنــه لــم يتقــدم لــي خاطــب قبــل اخلاطــب احلالــي فهــذا صحيــح وأنــا لســت‬\n‫صغيــرة بــل عمــري اآلن ســتة وعشــرون عامـ ًا وأمــا القطيعــة فأســرتنا مــع‬\n\n\n                                                                                         ‫‪118‬‬\n\f      ‫األســف فيهــا تفــكك وقطيعــة فأنــا ال أرى عماتــي منــذ صغــري ســوى‬\n      ‫مــرة أو مرتــن فقــط وكذلــك خاالتــي ووالــدي يعلــم بذلــك كمــا أن‬\n      ‫أخواتــي املتزوجــات ال يوجــد تواصــل بينهــم وبــن والــدي ووالدتــي فأنــا‬\n      ‫لــم أكــن الســبب يف القطيعــة التــي ذكــر بــل هــي موجــودة مــن قبــل‬\n      ‫وبعرضــه علــى املدعــى عليــه قــال مــا ذكرتــه املدعيــة مــن عــدم التواصــل‬\n      ‫بينهــا وبــن عماتهــا وخاالتهــا فهــو صحيــح ثــم قالــت املدعيــة لقــد صدرت‬\n      ‫موافقــة وزارة الداخليــة علــى زواجــي مــن اخلاطــب لــي باخلطــاب الــوارد‬\n      ‫إلمــارة الشــرقية مــن وكيــل وزارة الداخليــة لشــؤن احلقــوق برقــم ‪40801‬‬\n      ‫يف ‪1434/4/8‬ه ـ كمــا ورد التقريــر الطبــي رقــم ‪ 41/516/1147‬يف‬\n      ‫‪1434/1/19‬ه ـ املتضمــن ســامة الطرفــن مــن األمــراض املعديــة‬\n      ‫وعــدم وجــود مانــع مــن اســتكمال إجــراءات الــزواج فســألت الطرفــن‬\n      ‫ألديكمــا زيــادة علــى مــا مت ذكــره مــن قبــل فقــال املتداعيــان ال زيــادة‬\n      ‫لنــا علــى مــا ســبق ذكــره إال أن املدعيــة قالــت أن والــدي قــد تــزوج بامرأة‬\n      ‫مصريــة اجلنســية وأبــن عمتــي متــزوج بلبنانيــة اجلنســية وعليــه فــإن الــزواج‬\n      ‫مــن األجانــب ليــس مبســتغرب يف أســرتنا وبعرضــه علــى املدعــى عليــه‬\n      ‫قــال مــا ذكرتــه املدعيــة صحيــح وقــد تزوجــت بامــرأة مصريــة ولكننــي‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث طالبــت‬         ‫طلقتهــا فبنـ ً‬\n      ‫املدعيــة بتزويجهــا مــن اخلاطــب لهــا احلاضــر يف هــذه اجللســة املدعــو (‪).....‬‬\n      ‫وأجــاب املدعــى عليــه بأنــه ال مانــع مــن تزويجهــا لــه بعــد الســؤال عنــه ومت‬\n      ‫ـاء علــى طلبــه لذلــك ولــم يقــدم جواب ـ ًا مالقي ـ ًا ثــم‬\n                                                                 ‫اعطــاؤه مهلــة شــهر بنـ ً‬\n      ‫يف هــذه اجللســة قــرر امتناعــه عــن التزويــج لألســباب التــي أوردهــا أعــاه‬\n      ‫وقــد مت مناقشــة املدعيــة عنهــا وأجابــت بــأن اخلاطــب لهــا ال يوجــد فيــه‬\n      ‫مــا مينــع مــن تزويجــه بهــا وذكــرت أنهــا تقيــم يف دار احلمايــة منــذ ســنتني‬\n\n\n‫‪119‬‬\n\f‫وذكــرت تقدمهــا يف الســن وحاجتهــا للــزواج كمــا ذكــرت أن اخلــاف‬\n‫والتقاطــع يف االســرة موجــود قبــل اخلــاف الواقــع بينهــا وبــن والدهــا‬\n‫وقــد صادقهــا والدهــا املدعــى عليــه علــى ذلــك كمــا ذكــرت وجــود‬\n‫الــزواج مــن االجانــب يف أســرتها وقــد مت االطــاع علــى موافقــة وزارة‬\n‫الداخليــة علــى الــزواج بــن املدعيــة وخاطبهــا واملذكــورة أعــاه واملرفقة‬\n‫يف املعاملــة كمــا مت االطــاع علــى التقاريــر الطبيــة للخاطــب واملدعيــة‬\n‫وحيــث ان العضــل هــو أن مينــع الولــي موليتــه مــن الــزواج بالكــفء الــذي‬\n‫ترضــاه ولعــدم تقــدمي املدعــى عليــه مــا مينــع مــن قبــول اخلاطــب إلبنتــه‬\n‫املدعيــة واختــاف اجلنســية ال يكــون مانعـ ًا واحلــال بــن الطرفــن كمــا‬\n‫هــو مــدون أعــاه ومــع وجــود الكفــاءة يف الديــن واخللــق وألن يف عضــل‬\n‫املدعيــة مــن الــزواج مــن الكــفء الــذي رضيتــه أضــرار بهــا والضــرر‬\n‫يــزال ولقــول النبــي صلــى اهلل عليــه وســلم (ال ضــرر وال ضــرار) وحيــث‬\n‫ان الولــي االقــرب إذا عضــل موليتــه انتقلــت الواليــة إلــى الســلطان وهــو‬\n‫احلاكــم الشــرعي علــى القــول املختــار ولــدرء املفســدة الناشــئة مــن تنــازع‬\n‫األوليــاء واختالفهــم وحيــث مت عــرض الصلــح بــن الطرفــن ولــم نتوصــل‬\n‫إلــى نتيجــة كمــا مت إقنــاع األب بتوكيــل غيــره يف التزويــج ليذهــب مــا‬\n‫يف نفســه مــن احلــرج بســبب اخلــاف الواقــع بينــه وبــن ابنتــه فلــم يوافــق‬\n‫وعليــه وجلميــع مــا ســبق فقــد ثبــت لــدي عضــل املدعــى عليــه البنتــه‬\n‫املدعيــة وفســخت واليتــه عنهــا ويتولــى تزويجهــا احلاكــم الشــرعي‬\n‫وبذلــك حكمــت وبعــرض احلكــم علــى املتداعيــن قنعــت املدعيــة ولــم‬\n‫يقنــع املدعــى عليــه وطالــب بإســتئناف احلكــم واســتعد بتقــدمي الئحــة‬\n‫اعتراضيــة وافهــم بالتعليمــات وســيتم تســليمه نســخة مــن احلكــم يف‬\n‫هــذا اليــوم بــإذن اهلل وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n\n\n                                                                                     ‫‪120‬‬\n\f                            ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/7/29‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافق‪1434/11/12‬ه ـ‬\n      ‫وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية باخلطــاب‬\n      ‫رقــم ‪ 34/2021865‬يف ‪1434/11/5‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن دائــرة األحــوال الشــخصية األولــى يف ‪1434/10/27‬ه ـ واملتضمــن‬\n      ‫مالحظــة أصحــاب الفضيلــة بقولهــم (لــم جنــد أن فضيلــة القاضــي طلــب‬\n      ‫البينــة علــى أن اخلاطــب كــفء للمدعيــة املخطوبــة يف الديــن واخللــق وال‬\n      ‫بــد مــن طلــب البينــة وتعديلهــا التعديــل الشــرعي ) وقــد حضــر للشــهادة‬\n      ‫ال مــن (‪ ).....‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪).....‬‬‫وأدائهــا ك ً‬\n      ‫ســعودي اجلنســية وبســؤالهما عمــا لديهــم مــن شــهادة شــهد كل واحــد‬\n      ‫ا أشــهد بــأن اخلاطــب كفــوء للمدعيــة املخطوبــة يف‬   ‫منهمــا مبفــرده قائـ ً‬\n      ‫الديــن واخللــق وجــرى تعديلهــم مــن قبــل (‪ ).....‬ســعودي اجلنســية و(‪).....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬وعليــه فــإن مــا‬\n      ‫صــدر منــي علــى حالــه وأمــرت بإعــادة املعاملــة حملكمــة االســتئناف‬\n      ‫باملنطقــة الشــرقية مــع الشــكر والتقديــر ألصحــاب الفضيلــة وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                              ‫يف ‪1434/11/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬مســاعد رئيــس احملكمــة‬\n      ‫العامــة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n                                                                                  ‫ّ‬\n      ‫العامــة مبحافظــة القطيــف برقــم ‪ 34260520‬وتاريــخ ‪1434/06/06‬ه ـ‬            ‫َ‬\n      ‫املقيــدة باحملكمــة وتاريــخ ‪1434/06/06‬ه ـ ففــي يــوم االثنــن املوافــق‬\n      ‫‪1434/12/02‬ه قــد وردتنــا املعاملــة مــن محكمــة االســتئناف باملنطقــة‬\n      ‫الشــرقية باخلطــاب رقــم ‪ 34/2638532‬يف ‪1434/11/26‬ه ـ املرفــق بــه‬\n\n\n‫‪121‬‬\n\f‫قــرار الدائــرة األولــى لألحــوال الشــخصية يف ‪1434/11/24‬هـ املتضمن‬\n‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل‬\n  ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/12/2‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة باحملكمة‪/‬ش‪1‬وتاريخ‪1434/11/20‬ه ـ الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة (‪ ).....‬وتاريــخ ‪1434/11/12‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيل ــة مســاعد رئيســها الشــيخ (‪).....‬‬\n‫وتاريخ‪1434/7/29‬هـ ـ اخلــاص بدعــوى(‪ ).....‬يف قضيــة عضــل ولــي‬\n‫املالحــظ عليــه بقــرار الدائــرة وتاريــخ ‪1434/10/27‬ه ـ وباالطــاع علــى‬\n‫مــا أجــره فضيلتــه جوابـ ًا علــى قــرار الدائــرة املشــار إليــه قررنــا املصادقــة‬\n‫علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                 ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/11/23‬هــ‪.‬‬\n\n\n\n\n                                                                                         