                                                          ‫الشــرعيةِ‪.‬‬  ‫األد َّل ِــة َّ‬\n      ‫ـامي يف الــدور ِة السادس ـ َة‬‫ـاء ِض ْمـ َـن قــراراتِ املجمـ ِـع الفِ قهـ ِّـي اإلسـ ِّ‬    ‫‪ -‬جـ َ‬\n      ‫نصــه (ال يجــو ُز االعتمــا ُد علــى البصم ـ ِة الوراثي ـ ِة يف نفـ ِـي‬          ‫عشــر َة َمــا ُّ‬\n                                      ‫ميهــا يف نفـ ِـي ال َّنسـ ِـب)‪.‬‬\n                                                                     ‫النسـ ِـب‪ ،‬وال يجــو ُز تقد ُ‬\n\n\n\n\n‫‪125‬‬\n\f‫ـزو َج شــقيق َته بواليـ ِة‬                     ‫املد َعــى عليـ ِه ‪ ......‬ابـ ُـن عم ِتــه وقَ ــد تـ َّ‬              ‫أن َّ‬        ‫املدعِ ــي َّ‬     ‫ا َّد َعــى َّ‬\n‫والدِ هــا يف ‪1418/1/1‬ه ـ ‪ ،‬ثـ َّـم ظــلَّ يتــر َّد ُد علي َهــا يف بيـ ِـت والــدِ ه ا َّلــذي‬\n‫زار ْت‬  ‫وكان يخت ِلــي بهــا‪ ،‬ثـ َّـم َ‬                        ‫َ‬               ‫تقريبــا‬\n                                                                                      ‫ً‬          ‫ـكن في ـ ِه شــقيق ُته ملــد ِة ســن ٍة‬               ‫تسـ ُ‬\n‫املد َعــى علي َهــا ويف‬                   ‫شــقيق ُته مـ َـع بقيـ ِة أخو ِتــه بيـ َـت عم ِتهــا ا َّلتــي هـ َـي والــد ُة َّ‬\n‫ـس مـ َـع‬        ‫املدعِ ــي أنْ جتلـ َ‬              ‫املد َعــى عليـ ِه مِ ــن ُأخـ ِـت َّ‬                ‫طلبـ ْـت والــد ُة َّ‬    ‫أثنــا ِء الزيــار ِة َ‬\n‫وأجنبـ ْـت‬\n         ‫َ‬                 ‫جامعهــا‬‫َ‬                ‫معــه ثـ َّـم‬‫فجلسـ ْـت َ‬ ‫َ‬              ‫املد َعــى علي ـ ِه علــى انفــرا ٍد‬                   ‫زوجهــا َّ‬\n                                                                                                                                                            ‫ِ‬\n‫املد َعــى علي ـ ِه هــذ ِه البنـ َـت ‪ ،‬وطلـ َـب‬                                    ‫أنكـ َـر َّ‬     ‫ـاع بن ًتــا‪ ،‬وقَ ــد َ‬           ‫إثـ َـر ذلـ َـك اجلمـ ِ‬\n‫ـأن أخ َتــه‬        ‫علمــا بـ َّ‬      ‫املد َعــى علي ـ ِه ً‬               ‫ـات نسـ ِـب هــذ ِه البنـ ِـت مـ َـن َ